package com.prometheus.clq.data

import com.prometheus.clq.model.Difficulty
import com.prometheus.clq.model.Question

object QuestionsExpansion12 {
    fun get(): List<Question> = listOf(
        Question(8500, "Quel est le symbole chimique de l'or?", listOf("Au", "Or", "Go", "Ag"), 0, "Science", Difficulty.EASY, explanation = "Le symbole Au vient du latin \"aurum\", qui signifie \"or\". C'est un métal précieux utilisé en joaillerie et en électronique."),
        Question(8501, "Combien de planètes y a-t-il dans notre système solaire?", listOf("8", "9", "10", "7"), 0, "Science", Difficulty.EASY, explanation = "En 2006, l'Union astronomique internationale a redéfini le terme \"planète\", rétrogradant Pluton au rang de planète naine, ce qui ramène le nombre officiel à huit."),
        Question(8502, "Quel gaz les plantes utilisent-elles principalement pour la photosynthèse?", listOf("CO2", "O2", "N2", "H2"), 0, "Science", Difficulty.EASY, explanation = "Le dioxyde de carbone (CO2) est absorbé par les feuilles via les stomates et, avec l'eau et la lumière, permet la synthèse de glucides lors de la photosynthèse."),
        Question(8503, "Quel est le plus grand océan du monde?", listOf("Océan Pacifique", "Océan Atlantique", "Océan Indien", "Océan Arctique"), 0, "Science", Difficulty.EASY, explanation = "L'océan Pacifique couvre environ 165 millions de kilomètres carrés, soit plus du tiers de la surface terrestre, ce qui en fait le plus vaste et le plus profond des océans."),
        Question(8504, "Quelle est la vitesse de la lumière?", listOf("300 000 km/s", "150 000 km/s", "500 000 km/s", "100 000 km/s"), 0, "Science", Difficulty.MEDIUM, explanation = "La vitesse de la lumière dans le vide est d'environ 300 000 kilomètres par seconde, une constante fondamentale de la physique notée c. Cette valeur est utilisée dans la théorie de la relativité d'Einstein et pour définir le mètre."),
        Question(8505, "Quel élément chimique a pour numéro atomique 1?", listOf("Hydrogène", "Hélium", "Lithium", "Carbone"), 0, "Science", Difficulty.EASY, explanation = "L'hydrogène est l'élément le plus léger et le plus abondant de l'univers, avec un seul proton dans son noyau, ce qui lui donne le numéro atomique 1."),
        Question(8506, "Combien de côtés a un hexagone?", listOf("6", "8", "5", "7"), 0, "Science", Difficulty.EASY, explanation = "Un hexagone est une figure géométrique à six côtés, le préfixe \"hexa-\" venant du grec ancien signifiant six."),
        Question(8507, "Quel scientifique a formulé la théorie de la relativité?", listOf("Albert Einstein", "Isaac Newton", "Galileo Galilei", "Stephen Hawking"), 0, "Science", Difficulty.EASY, explanation = "Albert Einstein a publié sa théorie de la relativité restreinte en 1905, puis la relativité générale en 1915, révolutionnant la compréhension de l'espace, du temps et de la gravitation."),
        Question(8508, "Quel est le plus haut sommet du monde?", listOf("Mont Everest", "Mont Kilimandjaro", "Mont Blanc", "K2"), 0, "Science", Difficulty.EASY, explanation = "L'Everest culmine à 8 849 mètres d'altitude dans l'Himalaya, à la frontière entre le Népal et le Tibet. Il a été nommé d'après le géomètre britannique George Everest."),
        Question(8509, "Quelle est la formule chimique de l'eau?", listOf("H2O", "CO2", "O2", "H2"), 0, "Science", Difficulty.EASY, explanation = "La molécule d'eau est composée de deux atomes d'hydrogène et un atome d'oxygène, d'où la formule H2O."),
        Question(8510, "Quel est le symbole chimique du fer?", listOf("Fe", "Fr", "F", "Fa"), 0, "Science", Difficulty.EASY, explanation = "Le symbole chimique du fer, Fe, vient du latin \"ferrum\". Il est utilisé dans le tableau périodique des éléments."),
        Question(8511, "Combien de dents permanentes a un humain adulte?", listOf("32", "28", "30", "36"), 0, "Science", Difficulty.MEDIUM, explanation = "Un humain adulte possède 32 dents permanentes, incluant 8 incisives, 4 canines, 8 prémolaires et 12 molaires (dont 4 dents de sagesse)."),
        Question(8512, "Quel est le plus grand organe du corps humain?", listOf("Peau", "Foie", "Cœur", "Cerveau"), 0, "Science", Difficulty.EASY, explanation = "La peau est considérée comme le plus grand organe car elle recouvre l'ensemble du corps et représente environ 15 % du poids total d'un adulte."),
        Question(8513, "Quel élément chimique est représenté par le symbole C?", listOf("Carbone", "Calcium", "Cadmium", "Curium"), 0, "Science", Difficulty.EASY, explanation = "Le symbole chimique C vient du latin carbo, qui signifie charbon, et désigne l'élément carbone, numéro atomique 6, essentiel à la vie."),
        Question(8514, "Quelle planète est la plus proche du Soleil?", listOf("Mercure", "Vénus", "Terre", "Mars"), 0, "Science", Difficulty.EASY, explanation = "Mercure est la planète la plus proche du Soleil, avec une distance moyenne d'environ 58 millions de kilomètres."),
        Question(8515, "Quel est le symbole chimique de l'argent?", listOf("Ag", "S", "Si", "Sr"), 0, "Science", Difficulty.EASY, explanation = "Le symbole Ag vient du latin \"argentum\", qui signifie argent. C'est un métal précieux utilisé depuis l'Antiquité."),
        Question(8516, "Combien de continents y a-t-il?", listOf("7", "6", "5", "8"), 1, "Science", Difficulty.MEDIUM, explanation = "Le nombre de continents varie selon les modèles géographiques. Le modèle le plus courant en France en compte six : Afrique, Amérique, Antarctique, Asie, Europe et Océanie."),
        Question(8517, "Quel est le plus grand désert du monde?", listOf("Antarctique", "Sahara", "Gobi", "Kalahari"), 0, "Science", Difficulty.MEDIUM, explanation = "L'Antarctique est considéré comme le plus grand désert du monde car il reçoit très peu de précipitations, moins de 50 mm par an en moyenne, ce qui correspond à la définition climatique d'un désert."),
        Question(8518, "Quel gaz représente environ 21% de l'atmosphère terrestre?", listOf("Oxygène", "Azote", "Dioxyde de carbone", "Argon"), 0, "Science", Difficulty.MEDIUM, explanation = "L'oxygène est le deuxième gaz le plus abondant dans l'atmosphère terrestre, constituant environ 21% de son volume, essentiel à la respiration des êtres vivants."),
        Question(8519, "Quel scientifique a découvert la pénicilline?", listOf("Alexander Fleming", "Louis Pasteur", "Marie Curie", "Jonas Salk"), 0, "Science", Difficulty.MEDIUM, explanation = "Alexander Fleming a découvert la pénicilline en 1928 en observant qu'une moisissure, le Penicillium notatum, inhibait la croissance de bactéries."),
        Question(8520, "Quel est le plus petit os du corps humain?", listOf("Étrier", "Marteau", "Enclume", "Radius"), 0, "Science", Difficulty.HARD, explanation = "L'étrier, situé dans l'oreille moyenne, mesure environ 3 millimètres et transmet les vibrations sonores au vestibule de l'oreille interne."),
        Question(8521, "Quelle est la température normale du corps humain en Celsius?", listOf("37", "36", "38", "35"), 0, "Science", Difficulty.EASY, explanation = "La température corporelle normale est maintenue autour de 37°C par l'hypothalamus, qui régule l'équilibre thermique du corps. Cette valeur peut varier légèrement selon l'activité et l'heure de la journée."),
        Question(8522, "Combien de chromosomes a un humain?", listOf("46", "44", "48", "50"), 0, "Science", Difficulty.MEDIUM, explanation = "Le génome humain est organisé en 23 paires de chromosomes, soit 46 au total, héritées pour moitié de chaque parent."),
        Question(8523, "Quel est le symbole chimique du sodium?", listOf("Na", "S", "Ne", "Ni"), 0, "Science", Difficulty.MEDIUM, explanation = "Le symbole Na vient du latin *natrium*, nom historique du sodium. C’est un métal alcalin très réactif, présent dans le sel de table (NaCl)."),
        Question(8524, "Quel est le plus grand mammifère du monde?", listOf("Baleine bleue", "Éléphant", "Girafe", "Ours polaire"), 0, "Science", Difficulty.EASY, explanation = "La baleine bleue peut atteindre 30 mètres de long et peser jusqu'à 200 tonnes, ce qui en fait le plus grand animal ayant jamais existé sur Terre."),
        Question(8525, "Quelle est la densité de l'eau en g/cm³?", listOf("1", "2", "0.5", "1.5"), 0, "Science", Difficulty.MEDIUM, explanation = "La densité de l'eau pure est de 1 g/cm³ à 4°C, température à laquelle elle atteint sa masse volumique maximale. Cette valeur sert de référence pour mesurer la densité des autres substances."),
        Question(8526, "Quel élément chimique est un gaz noble?", listOf("Néon", "Hydrogène", "Oxygène", "Azote"), 0, "Science", Difficulty.MEDIUM, explanation = "Le néon fait partie de la famille des gaz nobles, qui sont des éléments chimiques très stables et peu réactifs, situés dans la dernière colonne du tableau périodique."),
        Question(8527, "Combien de minutes a une heure?", listOf("60", "100", "50", "70"), 0, "Science", Difficulty.EASY, explanation = "Une heure est divisée en 60 minutes selon le système sexagésimal hérité des Babyloniens."),
        Question(8528, "Quel est le plus rapide animal terrestre?", listOf("Guépard", "Lion", "Antilope", "Gazelle"), 0, "Science", Difficulty.EASY, explanation = "Le guépard peut atteindre 110 km/h en pointe sur de courtes distances, ce qui en fait le mammifère terrestre le plus rapide du monde."),
        Question(8529, "Quelle est la formule chimique du dioxyde de carbone?", listOf("CO2", "C2O", "CO", "C2O2"), 0, "Science", Difficulty.EASY, explanation = "Le dioxyde de carbone est composé d'un atome de carbone lié à deux atomes d'oxygène, d'où la formule CO2."),
        Question(8530, "Quel scientifique a découvert la radioactivité?", listOf("Marie Curie", "Pierre Curie", "Ernest Rutherford", "Niels Bohr"), 0, "Science", Difficulty.MEDIUM, explanation = "Marie Curie a découvert la radioactivité en 1896, en étudiant les rayons uraniques émis par l'uranium, ce qui lui a valu deux prix Nobel."),
        Question(8531, "Combien de pattes a une araignée?", listOf("8", "6", "10", "4"), 0, "Science", Difficulty.EASY, explanation = "Les araignées appartiennent à la classe des arachnides, qui se distinguent des insectes par leurs huit pattes, contre six pour ces derniers."),
        Question(8532, "Quel est le symbole chimique du chlore?", listOf("Cl", "C", "Ca", "Co"), 0, "Science", Difficulty.MEDIUM, explanation = "Le symbole Cl vient du latin \"chlorum\", dérivé du grec \"chloros\" signifiant vert pâle, en référence à la couleur du gaz. C'est un halogène très réactif."),
        Question(8533, "Quelle est la plus grande forêt du monde?", listOf("Forêt amazonienne", "Taïga", "Forêt du Congo", "Forêt tropicale de Bornéo"), 0, "Science", Difficulty.MEDIUM, explanation = "L'Amazonie s'étend sur environ 5,5 millions de km², principalement au Brésil, et dépasse largement la taïga sibérienne en superficie de forêt tropicale continue."),
        Question(8534, "Quel est le plus haut type de nuage?", listOf("Cirrus", "Cumulus", "Stratus", "Altocumulus"), 0, "Science", Difficulty.HARD, explanation = "Les cirrus sont des nuages élevés, formés de cristaux de glace, situés au-dessus de 6 000 mètres d'altitude. Ils sont les plus hauts dans la classification des nuages."),
        Question(8535, "Combien de secondes a une minute?", listOf("60", "100", "50", "70"), 0, "Science", Difficulty.EASY, explanation = "La minute est une unité de temps standard qui, par définition, contient 60 secondes, conformément au système sexagésimal hérité des Babyloniens."),
        Question(8536, "Quel est le symbole chimique du cuivre?", listOf("Cu", "Co", "Cr", "C"), 0, "Science", Difficulty.MEDIUM, explanation = "Le symbole Cu vient du latin cuprum, qui désignait le cuivre extrait de l'île de Chypre dans l'Antiquité."),
        Question(8537, "Quelle est l'unité de mesure de la force?", listOf("Newton", "Joule", "Pascal", "Watt"), 0, "Science", Difficulty.MEDIUM, explanation = "Le newton est l'unité dérivée du Système international qui quantifie la force, nommée en hommage à Isaac Newton pour ses travaux sur la mécanique classique."),
        Question(8538, "Quel est le plus grand fleuve du monde?", listOf("Nil", "Amazone", "Yangtsé", "Mississipi"), 1, "Science", Difficulty.MEDIUM, explanation = "L'Amazone est le plus grand fleuve du monde en volume d'eau déversé, avec un débit moyen d'environ 209 000 m³/s, bien supérieur à celui du Nil."),
        Question(8539, "Quel gaz est produit par la photosynthèse?", listOf("Oxygène", "Dioxyde de carbone", "Azote", "Hydrogène"), 0, "Science", Difficulty.EASY, explanation = "La photosynthèse utilise le dioxyde de carbone et l'eau, avec l'énergie solaire, pour produire du glucose et libérer de l'oxygène comme sous-produit."),
        Question(8540, "Quel est le point de fusion de la glace en Celsius?", listOf("0", "-10", "10", "-5"), 0, "Science", Difficulty.EASY, explanation = "Sous pression atmosphérique normale, la glace fond à 0 degré Celsius, ce qui correspond au point de congélation de l'eau pure."),
        Question(8541, "Quel scientifique a formulé les lois du mouvement?", listOf("Isaac Newton", "Albert Einstein", "Galileo Galilei", "Johannes Kepler"), 0, "Science", Difficulty.MEDIUM, explanation = "Isaac Newton a publié ses trois lois du mouvement dans son ouvrage \"Philosophiæ Naturalis Principia Mathematica\" en 1687, posant les bases de la mécanique classique."),
        Question(8542, "Combien de lobes a le cerveau humain?", listOf("2", "4", "3", "5"), 0, "Science", Difficulty.HARD, explanation = "Le cerveau humain est divisé en deux hémisphères, gauche et droit, chacun contrôlant des fonctions spécifiques."),
        Question(8543, "Quel est le symbole chimique du potassium?", listOf("K", "P", "Ka", "Ki"), 0, "Science", Difficulty.MEDIUM, explanation = "Le symbole chimique du potassium vient du latin \"kalium\", d'où la lettre K."),
        Question(8544, "Quelle est la distance moyenne Terre-Soleil?", listOf("150 millions km", "100 millions km", "200 millions km", "75 millions km"), 0, "Science", Difficulty.HARD, explanation = "Cette distance, appelée unité astronomique (UA), sert de référence pour mesurer les distances dans le système solaire. Elle correspond à environ 150 millions de kilomètres."),
        Question(8545, "Quel est le plus grand lac du monde?", listOf("Lac Caspienne", "Lac Supérieur", "Lac Victoria", "Lac Baïkal"), 0, "Science", Difficulty.HARD, explanation = "Le lac Caspienne est considéré comme le plus grand lac du monde en superficie, avec environ 371 000 km², bien qu'il soit salé et souvent qualifié de mer en raison de sa taille."),
        Question(8546, "Quel est le symbole chimique du magnésium?", listOf("Mg", "Mn", "Mo", "Mt"), 0, "Science", Difficulty.MEDIUM, explanation = "Le symbole Mg vient du latin \"magnesium\", dérivé de la région grecque de Magnésie où ce minéral était extrait."),
        Question(8547, "Quelle est la vitesse du son dans l'air?", listOf("343 m/s", "500 m/s", "200 m/s", "450 m/s"), 0, "Science", Difficulty.HARD, explanation = "La vitesse du son dans l'air à 20°C au niveau de la mer est d'environ 343 mètres par seconde, car elle dépend de la température et de la densité du milieu."),
        Question(8548, "Combien de muscles a le corps humain?", listOf("640", "500", "700", "800"), 0, "Science", Difficulty.HARD, explanation = "Le corps humain compte environ 640 muscles squelettiques, responsables des mouvements volontaires, bien que ce nombre varie légèrement selon les individus."),
        Question(8549, "Quel élément chimique est un halogène?", listOf("Fluor", "Néon", "Hélium", "Argon"), 0, "Science", Difficulty.HARD, explanation = "Le fluor fait partie de la famille des halogènes, qui comprend également le chlore, le brome, l'iode et l'astate, tous situés dans le groupe 17 du tableau périodique."),
        Question(8550, "Quel est le point d'ébullition de l'eau au niveau de la mer?", listOf("100°C", "90°C", "110°C", "95°C"), 0, "Science", Difficulty.EASY, explanation = "Au niveau de la mer, la pression atmosphérique standard est de 1 atmosphère, ce qui porte l'eau à ébullition à 100°C. Cette température diminue en altitude car la pression baisse."),
        Question(8551, "Quel scientifique a découvert les lois de l'hérédité?", listOf("Gregor Mendel", "Charles Darwin", "Jean-Baptiste Lamarck", "August Weismann"), 0, "Science", Difficulty.MEDIUM, explanation = "Gregor Mendel, moine et botaniste autrichien du XIXe siècle, a établi les principes fondamentaux de la génétique en étudiant les pois. Ses travaux, publiés en 1866, ont posé les bases des lois de l'hérédité."),
        Question(8552, "Quel est le plus grand océan par volume?", listOf("Océan Pacifique", "Océan Atlantique", "Océan Indien", "Océan Arctique"), 0, "Science", Difficulty.HARD, explanation = "L'océan Pacifique est le plus grand océan par volume en raison de sa superficie immense et de sa profondeur moyenne élevée, notamment avec la fosse des Mariannes. Il contient plus de la moitié de l'eau libre de la Terre."),
        Question(8553, "Combien d'espèces de fourmis existe-t-il environ?", listOf("20000", "10000", "5000", "50000"), 0, "Science", Difficulty.HARD, explanation = "On estime qu'il existe environ 20 000 espèces de fourmis dans le monde, bien que ce nombre puisse varier selon les découvertes scientifiques récentes."),
        Question(8554, "Quel est le symbole chimique du calcium?", listOf("Ca", "C", "Cd", "Co"), 0, "Science", Difficulty.EASY, explanation = "Le symbole chimique du calcium, Ca, vient du latin \"calx\" signifiant chaux. C'est un métal alcalino-terreux essentiel pour les organismes vivants."),
        Question(8555, "Quelle est la masse atomique du carbone?", listOf("12", "14", "10", "16"), 0, "Science", Difficulty.HARD, explanation = "Le carbone a un isotope majoritaire, le carbone 12, dont la masse atomique est définie comme exactement 12 unités de masse atomique."),
        Question(8556, "Quel scientifique a théorisé l'évolution?", listOf("Charles Darwin", "Jean-Baptiste Lamarck", "Gregor Mendel", "Alfred Russel Wallace"), 0, "Science", Difficulty.MEDIUM, explanation = "Charles Darwin a publié en 1859 \"L'Origine des espèces\", posant les bases de la théorie de l'évolution par sélection naturelle."),
        Question(8557, "Combien de nerfs crâniens a un humain?", listOf("12", "10", "14", "8"), 0, "Science", Difficulty.HARD, explanation = "Les humains possèdent 12 paires de nerfs crâniens, qui émergent directement du cerveau et du tronc cérébral pour innerver la tête, le cou et certaines fonctions viscérales."),
        Question(8558, "Quel élément chimique a le numéro atomique 8?", listOf("Oxygène", "Azote", "Carbone", "Bore"), 0, "Science", Difficulty.MEDIUM, explanation = "Le numéro atomique 8 correspond au nombre de protons dans le noyau de l'atome d'oxygène, un élément essentiel à la respiration et présent dans l'air."),
        Question(8559, "Quel est le plus petit minéral connu?", listOf("Quartz", "Feldspath", "Mica", "Calcite"), 2, "Science", Difficulty.EXPERT, explanation = "Le mica est considéré comme le plus petit minéral connu car il peut se présenter en feuillets extrêmement fins, parfois d’une épaisseur de quelques atomes seulement."),
        Question(8560, "Quelle est l'unité de mesure de la pression?", listOf("Pascal", "Newton", "Joule", "Watt"), 0, "Science", Difficulty.MEDIUM, explanation = "Le pascal (Pa) est l'unité dérivée du Système international pour la pression, définie comme une force d'un newton appliquée sur une surface d'un mètre carré."),
        Question(8561, "Quel gaz représente environ 78% de l'atmosphère?", listOf("Azote", "Oxygène", "Argon", "Néon"), 0, "Science", Difficulty.MEDIUM, explanation = "L'azote est le gaz le plus abondant dans l'atmosphère terrestre, constituant environ 78% de son volume, suivi par l'oxygène à 21%."),
        Question(8562, "Quel scientifique a inventé le microscope?", listOf("Zacharias Janssen", "Galilée", "Robert Hooke", "Anton van Leeuwenhoek"), 0, "Science", Difficulty.HARD, explanation = "Zacharias Janssen, un fabricant de lunettes néerlandais, est crédité de l'invention du premier microscope composé vers 1590, avec l'aide de son père Hans."),
        Question(8563, "Combien de côtés a un pentagone?", listOf("5", "6", "4", "7"), 0, "Science", Difficulty.EASY, explanation = "Un pentagone est un polygone à cinq côtés, le préfixe \"penta-\" venant du grec ancien pour cinq."),
        Question(8564, "Quel est le symbole chimique du phosphore?", listOf("P", "Po", "Pb", "Pr"), 0, "Science", Difficulty.MEDIUM, explanation = "Le symbole chimique du phosphore est P, car il correspond à la première lettre de son nom latin, Phosphorus."),
        Question(8565, "Quelle est la profondeur de la Fosse des Mariannes?", listOf("11000 m", "8000 m", "15000 m", "6000 m"), 0, "Science", Difficulty.HARD, explanation = "La Fosse des Mariannes est le point le plus profond des océans, avec une profondeur maximale d'environ 11 000 mètres dans le Challenger Deep."),
        Question(8566, "Quel élément chimique est le plus abondant dans l'univers?", listOf("Hydrogène", "Hélium", "Carbone", "Oxygène"), 0, "Science", Difficulty.HARD, explanation = "L'hydrogène représente environ 75% de la matière baryonique de l'univers, formé lors du Big Bang. Il est le combustible principal des étoiles par fusion nucléaire."),
        Question(8567, "Combien de paires de côtes a un humain?", listOf("12", "10", "14", "11"), 0, "Science", Difficulty.HARD, explanation = "Le squelette humain possède 12 paires de côtes, soit 24 côtes au total, qui protègent les organes thoraciques comme le cœur et les poumons."),
        Question(8568, "Quel scientifique a découvert l'électron?", listOf("J.J. Thomson", "Ernest Rutherford", "Niels Bohr", "Max Planck"), 0, "Science", Difficulty.HARD, explanation = "J.J. Thomson découvrit l'électron en 1897 lors d'expériences sur les rayons cathodiques, ce qui lui valut le prix Nobel de physique en 1906."),
        Question(8569, "Quel est le symbole chimique du soufre?", listOf("S", "Se", "Si", "Sn"), 0, "Science", Difficulty.MEDIUM, explanation = "Le symbole chimique du soufre est S, car il dérive de son nom latin *sulfur*. Cet élément non métallique est présent dans la nature sous forme de cristaux jaunes et dans de nombreux minéraux."),
        Question(8570, "Quelle est la température à la surface du Soleil?", listOf("5500°C", "3000°C", "8000°C", "2000°C"), 0, "Science", Difficulty.HARD, explanation = "La température à la surface du Soleil, appelée photosphère, est d'environ 5500°C, ce qui correspond à la lumière visible que nous recevons."),
        Question(8571, "Quel gland produit l'insuline?", listOf("Pancréas", "Thyroïde", "Surrénale", "Hypophyse"), 0, "Science", Difficulty.MEDIUM, explanation = "Le pancréas produit l'insuline via ses îlots de Langerhans, des cellules endocrines spécialisées qui régulent la glycémie."),
        Question(8572, "Quel est le plus grand glacier du monde?", listOf("Inlandsis du Groenland", "Inlandsis de l'Antarctique", "Glacier d'Aletsch", "Glacier d'Humboldt"), 1, "Science", Difficulty.HARD, explanation = "L'inlandsis de l'Antarctique est le plus grand glacier du monde, couvrant environ 14 millions de km² et contenant 90 % de la glace terrestre."),
        Question(8573, "Quel scientifique a découvert l'ADN?", listOf("James Watson et Francis Crick", "Erwin Schrödinger", "Linus Pauling", "Rosalind Franklin"), 0, "Science", Difficulty.HARD, explanation = "La structure en double hélice de l'ADN a été découverte en 1953 par James Watson et Francis Crick, s'appuyant sur les travaux de Rosalind Franklin et Maurice Wilkins."),
        Question(8574, "Combien de côtés a un triangle?", listOf("3", "4", "5", "6"), 0, "Science", Difficulty.EASY, explanation = "Un triangle est une figure géométrique composée de trois segments de droite reliés entre eux, ce qui lui donne trois côtés."),
        Question(8575, "Quel est le symbole chimique du brome?", listOf("Br", "B", "Ba", "Be"), 0, "Science", Difficulty.HARD, explanation = "Le symbole chimique du brome est Br, dérivé du grec bromos signifiant puanteur, en raison de son odeur âcre. C'est un élément halogène liquide à température ambiante."),
        Question(8576, "Quelle est l'unité de mesure de l'énergie?", listOf("Joule", "Newton", "Pascal", "Watt"), 0, "Science", Difficulty.MEDIUM, explanation = "Le joule est l'unité dérivée du Système international pour quantifier l'énergie, le travail ou la chaleur, nommée d'après le physicien James Prescott Joule."),
        Question(8577, "Quel élément chimique est radioactif?", listOf("Uranium", "Or", "Argent", "Cuivre"), 0, "Science", Difficulty.MEDIUM, explanation = "L'uranium est un élément chimique radioactif car son noyau instable se désintègre spontanément en émettant des particules et de l'énergie, un processus utilisé dans les réacteurs nucléaires et les armes atomiques."),
        Question(8578, "Combien de vertèbres a la colonne vertébrale?", listOf("33", "30", "35", "40"), 0, "Science", Difficulty.HARD, explanation = "La colonne vertébrale humaine compte 33 vertèbres à la naissance, mais plusieurs fusionnent à l'âge adulte, réduisant ce nombre à 26."),
        Question(8579, "Quel scientifique a formulé la loi de la gravitation?", listOf("Isaac Newton", "Albert Einstein", "Galileo Galilei", "Johannes Kepler"), 0, "Science", Difficulty.EASY, explanation = "Isaac Newton a formulé la loi de la gravitation universelle dans son ouvrage \"Philosophiæ Naturalis Principia Mathematica\" en 1687, expliquant ainsi la chute des corps et le mouvement des planètes."),
        Question(8580, "Quel est le symbole chimique du zinc?", listOf("Zn", "Z", "Zr", "Zb"), 0, "Science", Difficulty.MEDIUM, explanation = "Le symbole Zn vient du latin zincum, adopté officiellement par l’Union internationale de chimie pure et appliquée (UICPA) pour désigner cet élément métallique de numéro atomique 30."),
        Question(8581, "Quelle est la longueur du cerveau humain moyen?", listOf("15 cm", "20 cm", "10 cm", "25 cm"), 0, "Science", Difficulty.HARD, explanation = "Le cerveau humain adulte mesure en moyenne 15 centimètres de long, de l'avant du lobe frontal à l'arrière du lobe occipital. Cette taille est corrélée au volume crânien et varie légèrement selon les individus."),
        Question(8582, "Quel gland produit l'hormone de croissance?", listOf("Hypophyse", "Thyroïde", "Surrénale", "Pancréas"), 0, "Science", Difficulty.HARD, explanation = "L'hypophyse, située à la base du cerveau, sécrète l'hormone de croissance, essentielle au développement et à la régénération des tissus."),
        Question(8583, "Quel est le plus grand désert froid du monde?", listOf("Antarctique", "Gobi", "Kalahari", "Namib"), 0, "Science", Difficulty.HARD, explanation = "L'Antarctique est considéré comme le plus grand désert froid du monde car il reçoit très peu de précipitations, moins de 50 mm par an en moyenne, ce qui correspond à la définition d'un désert."),
        Question(8584, "Quel scientifique a découvert la loi de Coulomb?", listOf("Charles-Augustin de Coulomb", "Michael Faraday", "Alessandro Volta", "Georg Ohm"), 0, "Science", Difficulty.EXPERT, explanation = "Charles-Augustin de Coulomb a énoncé cette loi fondamentale de l'électrostatique en 1785, décrivant la force entre deux charges électriques."),
        Question(8585, "Combien de lobes a le foie?", listOf("4", "2", "3", "5"), 0, "Science", Difficulty.HARD, explanation = "Le foie humain est divisé anatomiquement en quatre lobes : le lobe droit, le lobe gauche, le lobe caudé et le lobe carré."),
        Question(8586, "Quel est le symbole chimique du nickel?", listOf("Ni", "N", "Ne", "Na"), 0, "Science", Difficulty.HARD, explanation = "Le symbole Ni vient du latin Niccolum. Le nickel est un métal de transition, ferromagnétique, utilisé dans les alliages comme l'inox."),
        Question(8587, "Quelle est la masse du Soleil?", listOf("1.989 × 10³⁰ kg", "5 × 10³⁰ kg", "1 × 10³⁰ kg", "3 × 10³⁰ kg"), 0, "Science", Difficulty.EXPERT, explanation = "Le Soleil contient 99,86 % de la masse du système solaire, soit environ 1,989 × 10³⁰ kg, soit 330 000 fois la masse de la Terre."),
        Question(8588, "Quel élément chimique est utilisé pour la datation au carbone?", listOf("Carbone-14", "Carbone-12", "Uranium-238", "Potassium-40"), 0, "Science", Difficulty.HARD, explanation = "Le carbone-14 est un isotope radioactif du carbone, présent dans tous les êtres vivants, dont la désintégration régulière permet de dater des échantillons organiques jusqu'à environ 50 000 ans."),
        Question(8589, "Combien de neurones a le cerveau humain environ?", listOf("86 milliards", "50 milliards", "100 milliards", "200 milliards"), 0, "Science", Difficulty.EXPERT, explanation = "Le chiffre de 86 milliards de neurones a été établi par des études récentes en neurosciences, remplaçant l'estimation antérieure de 100 milliards souvent citée."),
        Question(8590, "Quel scientifique a découvert le neutron?", listOf("James Chadwick", "Ernest Rutherford", "Niels Bohr", "Max Planck"), 0, "Science", Difficulty.HARD, explanation = "James Chadwick a découvert le neutron en 1932 lors d'expériences de bombardement du béryllium par des particules alpha, ce qui lui a valu le prix Nobel de physique en 1935."),
        Question(8591, "Quel est le symbole chimique du tungstène?", listOf("W", "Tu", "Wg", "Tn"), 0, "Science", Difficulty.HARD, explanation = "Le symbole W vient de Wolfram, nom allemand du tungstène, dérivé du minerai wolframite."),
        Question(8592, "Quelle est la distance Terre-Lune?", listOf("384400 km", "300000 km", "500000 km", "250000 km"), 0, "Science", Difficulty.HARD, explanation = "La distance moyenne entre la Terre et la Lune est d'environ 384 400 kilomètres, mesurée entre leurs centres. Cette valeur varie légèrement en raison de l'orbite elliptique de la Lune."),
        Question(8593, "Quel gland produit la mélatonine?", listOf("Glande pinéale", "Thyroïde", "Hypophyse", "Pancréas"), 0, "Science", Difficulty.HARD, explanation = "La glande pinéale, située dans le cerveau, sécrète la mélatonine, une hormone qui régule le cycle veille-sommeil en réponse à l'obscurité."),
        Question(8594, "Quel est le plus grand continents en surface?", listOf("Asie", "Afrique", "Amérique du Nord", "Antarctique"), 0, "Science", Difficulty.EASY, explanation = "L'Asie est le plus grand continent avec une superficie d'environ 44,6 millions de kilomètres carrés, soit près d'un tiers des terres émergées de la planète."),
        Question(8595, "Quel scientifique a découvert les rayons X?", listOf("Wilhelm Röntgen", "Marie Curie", "Pierre Curie", "Henri Becquerel"), 0, "Science", Difficulty.MEDIUM, explanation = "Wilhelm Röntgen a découvert les rayons X en 1895, alors qu'il étudiait les rayons cathodiques."),
        Question(8596, "Quel est le symbole chimique de l'étain?", listOf("Sn", "St", "Si", "Sr"), 0, "Science", Difficulty.HARD, explanation = "Le symbole Sn vient du latin stannum, qui désignait l'étain. Ce métal est utilisé depuis l'Antiquité."),
        Question(8597, "Combien de côtés a un dodécagone?", listOf("12", "10", "8", "15"), 0, "Science", Difficulty.HARD, explanation = "Le préfixe \"dodéca\" signifie douze en grec, donc un dodécagone est un polygone à douze côtés."),
        Question(8598, "Quel élément chimique a le point de fusion le plus haut?", listOf("Tungstène", "Platine", "Carbone", "Iridium"), 0, "Science", Difficulty.EXPERT, explanation = "Le tungstène possède le point de fusion le plus élevé de tous les éléments, à 3422 °C, en raison de ses liaisons métalliques extrêmement fortes."),
        Question(8599, "Quelle est la masse de l'électron?", listOf("9.109 × 10⁻³¹ kg", "1.673 × 10⁻²⁷ kg", "6.642 × 10⁻²⁷ kg", "3.344 × 10⁻²⁷ kg"), 0, "Science", Difficulty.EXPERT, explanation = "L'électron a une masse d'environ 9,109 × 10⁻³¹ kg, soit 1/1836 de celle du proton. Cette valeur est une constante fondamentale de la physique."),
        Question(8600, "Quel scientifique a formulé l'équation E=mc²?", listOf("Albert Einstein", "Max Planck", "Niels Bohr", "Wolfgang Pauli"), 0, "Science", Difficulty.EASY, explanation = "Albert Einstein a publié cette équation en 1905 dans le cadre de sa théorie de la relativité restreinte, établissant l'équivalence entre masse et énergie."),
        Question(8601, "Combien de chromosomes a la Drosophile?", listOf("8", "46", "14", "23"), 0, "Science", Difficulty.EXPERT, explanation = "La drosophile possède 8 chromosomes (4 paires) dans ses cellules somatiques, une caractéristique classique des études génétiques."),
        Question(8602, "Quel est le symbole chimique du molybdène?", listOf("Mo", "Mb", "Mn", "Mg"), 0, "Science", Difficulty.HARD, explanation = "Le molybdène tire son symbole Mo de son nom latin Molybdaenum. C'est un métal de transition utilisé dans les alliages d'acier pour augmenter leur résistance à la chaleur."),
        Question(8603, "Quelle est la constante de Planck?", listOf("6.626 × 10⁻³⁴ J·s", "1.054 × 10⁻³⁴ J·s", "3.313 × 10⁻³⁴ J·s", "9.109 × 10⁻³¹ J·s"), 0, "Science", Difficulty.EXPERT, explanation = "La constante de Planck, notée h, relie l'énergie d'un photon à sa fréquence et est fondamentale en mécanique quantique. Sa valeur est 6,626 × 10⁻³⁴ joule-seconde."),
        Question(8604, "Quel gland régule le métabolisme?", listOf("Thyroïde", "Hypophyse", "Surrénale", "Pancréas"), 0, "Science", Difficulty.MEDIUM, explanation = "La glande thyroïde, située dans le cou, produit des hormones qui contrôlent la vitesse du métabolisme, influençant ainsi la dépense énergétique et la température corporelle."),
        Question(8605, "Quel est le plus grand volcan du monde?", listOf("Mauna Loa", "Mont Everest", "Krakatoa", "Vésuve"), 0, "Science", Difficulty.HARD, explanation = "Mauna Loa, situé à Hawaï, est le plus grand volcan du monde en volume et en superficie, s'élevant à plus de 9 000 mètres depuis le fond de l'océan Pacifique."),
        Question(8606, "Quel scientifique a découvert le proton?", listOf("Ernest Rutherford", "James Chadwick", "Niels Bohr", "Max Planck"), 0, "Science", Difficulty.HARD, explanation = "Ernest Rutherford a découvert le proton en 1919 lors de ses expériences de bombardement de l'azote avec des particules alpha."),
        Question(8607, "Quel est le symbole chimique du tantale?", listOf("Ta", "T", "Tb", "Tc"), 0, "Science", Difficulty.HARD, explanation = "Le tantale tire son symbole Ta de son nom latin, Tantalum. Il est utilisé dans l'industrie électronique pour ses condensateurs."),
        Question(8608, "Combien de muscles faciaux a un humain?", listOf("43", "30", "50", "60"), 0, "Science", Difficulty.HARD, explanation = "Le visage humain compte 43 muscles, responsables des expressions faciales comme le sourire ou le froncement de sourcils."),
        Question(8609, "Quel élément chimique est le plus lourd dans le tableau périodique?", listOf("Oganesson", "Livermorium", "Flerovium", "Copernicium"), 0, "Science", Difficulty.EXPERT, explanation = "L'oganesson (Og) est l'élément le plus lourd connu, avec un numéro atomique de 118. Synthétisé en 2002, il est instable et se désintègre rapidement."),
        Question(8610, "Quelle est la charge élémentaire?", listOf("1.602 × 10⁻¹⁹ C", "9.109 × 10⁻³¹ C", "6.626 × 10⁻³⁴ C", "1.673 × 10⁻²⁷ C"), 0, "Science", Difficulty.EXPERT, explanation = "La charge élémentaire, notée e, est la charge électrique d'un seul proton ou d'un électron. Elle vaut environ 1,602 × 10⁻¹⁹ coulombs."),
        Question(8611, "Quel scientifique a découvert le pôle magnétique?", listOf("Christophe Colomb", "Zheng He", "Vasco de Gama", "Ferdinand Magellan"), 3, "Science", Difficulty.HARD, explanation = "Ferdinand Magellan a observé la déviation de l'aiguille de la boussole lors de son expédition autour du monde, ce qui a conduit à la découverte du pôle magnétique terrestre."),
        Question(8612, "Quel est le symbole chimique du rhénium?", listOf("Re", "Rh", "Rb", "Rf"), 0, "Science", Difficulty.HARD, explanation = "Le rhénium, élément de numéro atomique 75, tire son symbole Re de son nom latin Rhenium, dérivé du Rhin."),
        Question(8613, "Quelle est la longueur de l'ADN humain?", listOf("2 mètres", "1 mètre", "3 mètres", "0.5 mètres"), 0, "Science", Difficulty.EXPERT, explanation = "L'ADN humain, si on déroule toutes ses molécules contenues dans une seule cellule, mesure environ 2 mètres de long. Cette longueur est rendue possible par un compactage extrême dans le noyau cellulaire."),
        Question(8614, "Quel gland produit la testostérone?", listOf("Testicule", "Prostate", "Glande de Cowper", "Ovaire"), 0, "Science", Difficulty.HARD, explanation = "Les testicules sont les glandes sexuelles masculines principales, responsables de la production de testostérone, l'hormone clé du développement masculin."),
        Question(8615, "Quel est le plus grand astéroïde du système solaire?", listOf("Cérès", "Vesta", "Pallas", "Junon"), 0, "Science", Difficulty.HARD, explanation = "Cérès, d'environ 940 km de diamètre, est le plus grand astéroïde de la ceinture principale entre Mars et Jupiter, et il est également classé comme planète naine."),
        Question(8616, "Quel scientifique a théorisé le big bang?", listOf("Georges Lemaître", "Edwin Hubble", "Stephen Hawking", "Albert Einstein"), 0, "Science", Difficulty.HARD, explanation = "Georges Lemaître, un chanoine et astrophysicien belge, a proposé en 1927 la théorie de l'atome primitif, qui est devenue la base du modèle du Big Bang."),
        Question(8617, "Quel est le symbole chimique du vanadium?", listOf("V", "Va", "Vb", "Vc"), 0, "Science", Difficulty.HARD, explanation = "Le symbole chimique du vanadium est V, car il dérive de son nom latin \"Vanadium\". C'est un métal de transition utilisé dans les alliages d'acier."),
        Question(8618, "Combien de chromosomes a une cellule de levure?", listOf("16", "23", "46", "8"), 0, "Science", Difficulty.EXPERT, explanation = "La levure de boulanger (Saccharomyces cerevisiae) possède 16 chromosomes, ce qui en fait un organisme modèle simple pour la recherche en génétique."),
        Question(8619, "Quel élément chimique est le plus conducteur de l'électricité?", listOf("Argent", "Cuivre", "Or", "Aluminium"), 0, "Science", Difficulty.HARD, explanation = "L'argent possède la plus haute conductivité électrique de tous les métaux, car ses électrons libres se déplacent avec une très faible résistance."),
        Question(8620, "Quelle est la masse du proton?", listOf("1.673 × 10⁻²⁷ kg", "9.109 × 10⁻³¹ kg", "1.675 × 10⁻²⁷ kg", "6.642 × 10⁻²⁷ kg"), 0, "Science", Difficulty.EXPERT, explanation = "Le proton, particule subatomique du noyau atomique, a une masse d'environ 1,673 × 10⁻²⁷ kg, soit 1836 fois celle de l'électron. Cette valeur est une constante fondamentale en physique."),
        Question(8621, "Quel scientifique a découvert la fission nucléaire?", listOf("Lise Meitner et Otto Frisch", "Enrico Fermi", "J. Robert Oppenheimer", "Richard Feynman"), 0, "Science", Difficulty.EXPERT, explanation = "Lise Meitner et Otto Frisch ont interprété les résultats des expériences d'Otto Hahn et Fritz Strassmann en 1938, démontrant la division du noyau d'uranium."),
        Question(8622, "Quel est le symbole chimique du titane?", listOf("Ti", "T", "Tb", "Tc"), 0, "Science", Difficulty.MEDIUM, explanation = "Le symbole chimique du titane est Ti, dérivé de son nom latin titanium. Il s'agit d'un métal de transition léger et résistant, utilisé dans les alliages aéronautiques."),
        Question(8623, "Combien de gènes a le génome humain environ?", listOf("20000-25000", "50000", "100000", "10000"), 0, "Science", Difficulty.HARD, explanation = "Les premières estimations du nombre de gènes humains étaient bien plus élevées, mais le séquençage complet du génome a révélé qu'il contient environ 20 000 à 25 000 gènes codant des protéines."),
        Question(8624, "Quel gland produit le cortisol?", listOf("Glande surrénale", "Thyroïde", "Hypophyse", "Pancréas"), 0, "Science", Difficulty.HARD, explanation = "Le cortisol est une hormone stéroïdienne sécrétée par la zone fasciculée du cortex surrénalien, situé dans les glandes surrénales au-dessus des reins."),
        Question(8625, "Quel est le plus grand lac d'eau douce du monde?", listOf("Lac Baïkal", "Lac Supérieur", "Lac Victoria", "Lac Tanganyika"), 0, "Science", Difficulty.HARD, explanation = "Le lac Baïkal, en Sibérie, est le plus grand lac d'eau douce du monde par volume d'eau, contenant environ 20 % des réserves mondiales d'eau douce non gelée."),
        Question(8626, "Quel scientifique a découvert le boson de Higgs?", listOf("Peter Higgs et François Englert", "Stephen Hawking", "Carl Sagan", "Neil deGrasse Tyson"), 0, "Science", Difficulty.EXPERT, explanation = "Le boson de Higgs a été prédit en 1964 par Peter Higgs et François Englert, qui ont reçu le prix Nobel de physique en 2013 pour cette découverte théorique."),
        Question(8627, "Quel est le symbole chimique du chrome?", listOf("Cr", "C", "Co", "Cu"), 0, "Science", Difficulty.MEDIUM, explanation = "Le symbole chimique du chrome, Cr, vient du latin \"chromium\", dérivé du grec \"chroma\" signifiant couleur, en raison des composés colorés de cet élément."),
        Question(8628, "Quelle est la température du centre de la Terre?", listOf("6000°C", "3000°C", "9000°C", "4000°C"), 0, "Science", Difficulty.HARD, explanation = "Le noyau terrestre, composé principalement de fer et de nickel, atteint environ 6000°C, soit une température similaire à celle de la surface du Soleil."),
        Question(8629, "Quel élément chimique est le plus léger?", listOf("Hydrogène", "Hélium", "Lithium", "Béryllium"), 0, "Science", Difficulty.MEDIUM, explanation = "L'hydrogène est l'élément le plus léger car son noyau ne contient qu'un seul proton, ce qui lui donne une masse atomique d'environ 1,008 u."),
        Question(8630, "Quel scientifique a découvert les ondes électromagnétiques?", listOf("James Clerk Maxwell", "Michael Faraday", "Heinrich Hertz", "Nikola Tesla"), 0, "Science", Difficulty.HARD, explanation = "James Clerk Maxwell a formulé les équations unifiant électricité et magnétisme, prédisant l'existence des ondes électromagnétiques en 1865."),
        Question(8631, "Quel est le symbole chimique du cobalt?", listOf("Co", "C", "Cb", "Cn"), 0, "Science", Difficulty.MEDIUM, explanation = "Le symbole chimique du cobalt provient de son nom latin \"cobaltum\". Il est utilisé dans les aimants et les batteries."),
        Question(8632, "Combien de paires de chromosomes a un humain?", listOf("23", "24", "22", "25"), 0, "Science", Difficulty.MEDIUM, explanation = "Les humains possèdent 23 paires de chromosomes, soit 46 au total, dont 22 paires autosomiques et une paire de chromosomes sexuels."),
        Question(8633, "Quel gland produit la parathormone?", listOf("Glande parathyroïde", "Thyroïde", "Hypophyse", "Surrénale"), 0, "Science", Difficulty.HARD, explanation = "La glande parathyroïde produit la parathormone, qui régule le taux de calcium dans le sang."),
        Question(8634, "Quel est le plus grand nuage de gaz du système solaire?", listOf("Grande Tache Rouge de Jupiter", "Tempête de Saturne", "Atmosphère de Neptune", "Atmosphère d'Uranus"), 0, "Science", Difficulty.EXPERT, explanation = "La Grande Tache Rouge de Jupiter est une gigantesque tempête anticyclonique composée de gaz, plus vaste que la Terre, qui dure depuis au moins 350 ans."),
        Question(8635, "Quel scientifique a découvert les lois de Kepler?", listOf("Johannes Kepler", "Tycho Brahe", "Galileo Galilei", "Isaac Newton"), 0, "Science", Difficulty.HARD, explanation = "Johannes Kepler a formulé ses trois lois décrivant le mouvement des planètes autour du Soleil au début du 17e siècle, en se basant sur les observations précises de Tycho Brahe."),
        Question(8636, "Quel est le symbole chimique du cadmium?", listOf("Cd", "C", "Ca", "Ce"), 0, "Science", Difficulty.HARD, explanation = "Le cadmium est un métal de transition dont le symbole chimique Cd provient de son nom latin, \"cadmia\". Il est utilisé dans les batteries et les pigments."),
        Question(8637, "Quelle est la concentration de l'ADN dans le noyau cellulaire?", listOf("3 mg/cm³", "1 mg/cm³", "5 mg/cm³", "0.5 mg/cm³"), 0, "Science", Difficulty.EXPERT, explanation = "La concentration d'ADN dans le noyau est d'environ 3 mg/cm³, une densité remarquable qui permet de stocker deux mètres d'ADN dans un noyau de quelques micromètres."),
        Question(8638, "Quel élément chimique est le plus dense?", listOf("Osmium", "Iridium", "Platine", "Tungstène"), 0, "Science", Difficulty.HARD, explanation = "L'osmium est l'élément le plus dense à température ambiante, avec une densité d'environ 22,59 g/cm³, surpassant légèrement l'iridium."),
        Question(8639, "Quel scientifique a découvert l'indice de réfraction?", listOf("Willebrord Snell", "Christiaan Huygens", "Isaac Newton", "René Descartes"), 0, "Science", Difficulty.EXPERT, explanation = "Willebrord Snell, un astronome et mathématicien néerlandais, a formulé en 1621 la loi mathématique décrivant la réfraction de la lumière, connue aujourd'hui sous le nom de loi de Snell-Descartes."),
        Question(8640, "Quel est le symbole chimique du rhénium?", listOf("Re", "Rh", "Rf", "Rb"), 0, "Science", Difficulty.HARD, explanation = "Le rhénium, élément de numéro atomique 75, tire son symbole Re de son nom latin Rhenium, dérivé du Rhin."),
        Question(8641, "Combien de cellules a le corps humain environ?", listOf("37 trillions", "100 trillions", "10 trillions", "50 trillions"), 0, "Science", Difficulty.HARD, explanation = "Le corps humain adulte est composé d'environ 37 trillions de cellules, un nombre estimé par des études scientifiques basées sur des modèles de taille et de densité cellulaires."),
        Question(8642, "Quel gland produit l'œstrogène?", listOf("Ovaire", "Utérus", "Hypophyse", "Thyroïde"), 0, "Science", Difficulty.MEDIUM, explanation = "L'œstrogène est une hormone sexuelle principalement produite par les ovaires chez la femme, jouant un rôle clé dans le cycle menstruel et la reproduction."),
        Question(8643, "Quel est le plus grand corps céleste du système solaire?", listOf("Soleil", "Jupiter", "Saturne", "Neptune"), 0, "Science", Difficulty.EASY, explanation = "Le Soleil est une étoile qui contient à lui seul 99,86% de la masse totale du système solaire, ce qui en fait le plus grand corps céleste de notre système."),
        Question(8644, "Quel scientifique a développé la mécanique quantique?", listOf("Werner Heisenberg et Erwin Schrödinger", "Albert Einstein", "Niels Bohr", "Max Planck"), 0, "Science", Difficulty.HARD, explanation = "Heisenberg a formulé le principe d'incertitude et la mécanique matricielle, tandis que Schrödinger a développé l'équation d'onde, posant les bases de la mécanique quantique moderne."),
        Question(8645, "Quel est le symbole chimique du mercure?", listOf("Hg", "Mc", "Mg", "Mn"), 0, "Science", Difficulty.MEDIUM, explanation = "Hg vient du latin hydrargyrum, qui signifie argent liquide, en référence à l'aspect métallique et liquide du mercure à température ambiante."),
        Question(8646, "Quelle est la distance de la Terre à la Lune en nombre de diamètres terrestres?", listOf("30", "10", "50", "20"), 0, "Science", Difficulty.HARD, explanation = "La distance moyenne Terre-Lune est d'environ 384 400 km, tandis que le diamètre terrestre est d'environ 12 742 km, ce qui donne un rapport d'environ 30."),
        Question(8647, "Quel élément chimique est un semi-conducteur?", listOf("Silicium", "Cuivre", "Fer", "Aluminium"), 0, "Science", Difficulty.HARD, explanation = "Le silicium est l'élément semi-conducteur le plus utilisé en électronique, car ses propriétés permettent de contrôler le courant électrique, ce qui est essentiel pour les puces et transistors."),
        Question(8648, "Quel scientifique a découvert le benzène?", listOf("Michael Faraday", "August Kekulé", "Friedrich Wöhler", "Justus Liebig"), 0, "Science", Difficulty.EXPERT, explanation = "Michael Faraday a isolé le benzène en 1825 à partir d'huile de gaz d'éclairage, marquant la première identification de ce composé organique fondamental."),
        Question(8649, "Quel est le symbole chimique du germanium?", listOf("Ge", "G", "Gm", "Gd"), 0, "Science", Difficulty.HARD, explanation = "Le symbole chimique du germanium est Ge, car il dérive de son nom latin \"Germanium\". Cet élément semi-conducteur est utilisé dans l'industrie électronique et les fibres optiques."),
        Question(8650, "Combien de côtés a un octogone?", listOf("8", "6", "10", "7"), 0, "Science", Difficulty.EASY, explanation = "Un octogone est un polygone à huit côtés, le préfixe \"octo-\" signifiant huit en grec."),
        Question(8651, "Quel gland produit la prolactine?", listOf("Hypophyse", "Thyroïde", "Surrénale", "Pancréas"), 0, "Science", Difficulty.HARD, explanation = "La prolactine est une hormone sécrétée par l'hypophyse, une glande située à la base du cerveau, qui joue un rôle clé dans la lactation."),
        Question(8652, "Quel est le plus grand satellite naturel du système solaire?", listOf("Ganymède", "Titan", "Callisto", "Io"), 0, "Science", Difficulty.HARD, explanation = "Ganymède, lune de Jupiter, est le plus grand satellite naturel du système solaire, avec un diamètre de 5 268 kilomètres, dépassant même la planète Mercure."),
        Question(8653, "Quel scientifique a découvert les lois de la thermodynamique?", listOf("Nicolas Léonard Sadi Carnot", "Rudolf Clausius", "Lord Kelvin", "Ludwig Boltzmann"), 0, "Science", Difficulty.EXPERT, explanation = "Sadi Carnot a jeté les bases du deuxième principe de la thermodynamique dans son ouvrage de 1824 sur le rendement des machines à vapeur, posant ainsi les fondements de cette science."),
        Question(8654, "Quel est le symbole chimique du gallium?", listOf("Ga", "G", "Gd", "Gb"), 0, "Science", Difficulty.HARD, explanation = "Le gallium, dont le symbole est Ga, est un métal rare qui fond à seulement 29,76 °C, soit dans la main. Il est utilisé dans l'électronique et les semi-conducteurs."),
        Question(8655, "Quelle est la vitesse orbitale de la Terre?", listOf("30 km/s", "20 km/s", "40 km/s", "15 km/s"), 0, "Science", Difficulty.HARD, explanation = "La Terre parcourt environ 940 millions de kilomètres par an sur son orbite autour du Soleil, ce qui correspond à une vitesse moyenne de 30 km/s."),
        Question(8656, "Quel élément chimique a le nombre atomique 79?", listOf("Or", "Argent", "Cuivre", "Platine"), 0, "Science", Difficulty.MEDIUM, explanation = "Le nombre atomique 79 correspond à l'or (symbole Au), un métal précieux utilisé en bijouterie et en électronique pour sa conductivité et sa résistance à la corrosion."),
        Question(8657, "Quel scientifique a découvert les rayons cathodiques?", listOf("J.J. Thomson", "Ernest Rutherford", "Niels Bohr", "Max Planck"), 0, "Science", Difficulty.HARD, explanation = "J.J. Thomson a découvert les rayons cathodiques en 1897 lors de ses expériences avec un tube à vide, ce qui l'a mené à identifier l'électron."),
        Question(8658, "Quel est le symbole chimique du technétium?", listOf("Tc", "T", "Ta", "Tb"), 0, "Science", Difficulty.HARD, explanation = "Le technétium, de symbole Tc, est un élément chimique radioactif artificiel, le plus léger des éléments sans isotope stable."),
        Question(8659, "Combien de cellules rouges du sang a un humain environ?", listOf("25 trillions", "10 trillions", "50 trillions", "100 trillions"), 0, "Science", Difficulty.HARD, explanation = "Un adulte possède environ 25 trillions de globules rouges, soit environ 40 à 45 % du volume sanguin total, renouvelés constamment par la moelle osseuse."),
        Question(8660, "Quel gland produit le glucagon?", listOf("Pancréas", "Foie", "Thyroïde", "Hypophyse"), 0, "Science", Difficulty.HARD, explanation = "Le glucagon est une hormone produite par les cellules alpha des îlots de Langerhans du pancréas, qui augmente le taux de sucre dans le sang."),
        Question(8661, "Quel est le plus grand cratère d'impact connu?", listOf("Bassin du Pôle Sud-Aitken", "Cratère de Chicxulub", "Cratère de Sudbury", "Cratère de Vredefort"), 0, "Science", Difficulty.EXPERT, explanation = "Le bassin du Pôle Sud-Aitken, situé sur la face cachée de la Lune, est le plus grand cratère d'impact connu du système solaire, avec un diamètre d'environ 2 500 kilomètres."),
        Question(8662, "Quel scientifique a découvert la supraconductivité?", listOf("Heike Kamerlingh Onnes", "Niels Bohr", "Albert Einstein", "Max Planck"), 0, "Science", Difficulty.EXPERT, explanation = "Heike Kamerlingh Onnes découvrit la supraconductivité en 1911 en observant la disparition de la résistance électrique du mercure à très basse température."),
        Question(8663, "Quel est le symbole chimique du rhuthenium?", listOf("Ru", "R", "Re", "Rf"), 0, "Science", Difficulty.HARD, explanation = "Le ruthénium, découvert en 1844, tire son symbole Ru de son nom latin Ruthenia, en référence à la Russie."),
        Question(8664, "Quelle est la masse volumique du diamant?", listOf("3.5 g/cm³", "2.5 g/cm³", "4.5 g/cm³", "1.5 g/cm³"), 0, "Science", Difficulty.HARD, explanation = "Le diamant est une forme cristalline du carbone dont la structure atomique très dense lui confère une masse volumique d'environ 3,5 g/cm³, nettement supérieure à celle du graphite (2,2 g/cm³)."),
        Question(8665, "Quel élément chimique est le point de transition?", listOf("Fer", "Nickel", "Cobalt", "Manganèse"), 0, "Science", Difficulty.HARD, explanation = "Le fer est appelé point de transition car il se situe au centre du tableau périodique, dans la première série des métaux de transition, et possède des propriétés typiques comme la formation d'ions colorés et des états d'oxydation variables."),
        Question(8666, "Quel scientifique a découvert la diffraction des rayons X?", listOf("Max von Laue", "William Henry Bragg", "William Lawrence Bragg", "Christoph Goedecker"), 0, "Science", Difficulty.EXPERT, explanation = "Max von Laue a découvert la diffraction des rayons X en 1912, en montrant qu'ils se comportent comme des ondes en traversant un cristal. Cette découverte lui a valu le prix Nobel de physique en 1914."),
        Question(8667, "Quel est le symbole chimique du palladium?", listOf("Pd", "P", "Pb", "Pm"), 0, "Science", Difficulty.HARD, explanation = "Le symbole Pd vient du nom latin du palladium, Palladium, dérivé de l'astéroïde Pallas. C'est un métal précieux du groupe du platine, utilisé en catalyse et en joaillerie."),
        Question(8668, "Combien de paires de branches bronchiales a un humain?", listOf("2", "3", "1", "4"), 0, "Science", Difficulty.HARD, explanation = "Les bronches se divisent en deux branches principales, une pour chaque poumon, d'où le terme de bronches souches droite et gauche."),
        Question(8669, "Quel gland produit l'épinéphrine?", listOf("Glande surrénale", "Pancréas", "Thyroïde", "Hypophyse"), 0, "Science", Difficulty.HARD, explanation = "L'épinéphrine, aussi appelée adrénaline, est une hormone produite par la médullosurrénale, la partie centrale des glandes surrénales situées au-dessus des reins."),
        Question(8670, "Quel est le plus grand volcan actif du monde?", listOf("Kilauea", "Mont Etna", "Sakurajima", "Merapi"), 0, "Science", Difficulty.HARD, explanation = "Le Kilauea est souvent considéré comme le plus grand volcan actif du monde en termes de volume et de surface, situé à Hawaï. Il est entré en éruption de manière quasi continue depuis 1983."),
        Question(8671, "Quel scientifique a découvert les lois de Pauling?", listOf("Linus Pauling", "Max Pauling", "Richard Pauling", "Robert Pauling"), 0, "Science", Difficulty.EXPERT, explanation = "Linus Pauling a découvert ces lois qui portent son nom, notamment les règles de Pauling sur la structure des cristaux ioniques et la liaison chimique."),
        Question(8672, "Quel est le symbole chimique du cadmium?", listOf("Cd", "C", "Ca", "Ce"), 0, "Science", Difficulty.HARD, explanation = "Le cadmium est un métal de transition, et son symbole chimique Cd vient de son nom latin, \"cadmia\". Il est souvent utilisé dans les batteries rechargeables."),
        Question(8673, "Quelle est la profondeur moyenne de l'océan?", listOf("3688 m", "5000 m", "2000 m", "4000 m"), 0, "Science", Difficulty.HARD, explanation = "La profondeur moyenne des océans est d'environ 3 688 mètres, calculée en divisant le volume total d'eau de mer par la surface océanique mondiale."),
        Question(8674, "Quel élément chimique a le point d'ébullition le plus bas?", listOf("Hélium", "Hydrogène", "Néon", "Azote"), 0, "Science", Difficulty.HARD, explanation = "L'hélium est l'élément avec le point d'ébullition le plus bas car ses atomes sont très légers et interagissent faiblement, ce qui lui permet de rester liquide seulement à -268,9 °C."),
        Question(8675, "Quel scientifique a découvert le photon?", listOf("Albert Einstein", "Max Planck", "Niels Bohr", "Werner Heisenberg"), 0, "Science", Difficulty.HARD, explanation = "Einstein a proposé l'existence du photon en 1905 pour expliquer l'effet photoélectrique, ce qui lui a valu le prix Nobel de physique en 1921."),
        Question(8676, "Quel est le symbole chimique du tantale?", listOf("Ta", "T", "Tb", "Tc"), 0, "Science", Difficulty.HARD, explanation = "Le tantale a pour symbole chimique Ta, dérivé de son nom latin Tantalum. Il s'agit d'un métal de transition rare utilisé dans l'électronique."),
        Question(8677, "Combien de lobes a le poumon droit?", listOf("3", "2", "4", "5"), 0, "Science", Difficulty.HARD, explanation = "Le poumon droit possède trois lobes (supérieur, moyen et inférieur) pour s'adapter à l'espace laissé par le foie, contrairement au poumon gauche qui n'en a que deux."),
        Question(8678, "Quel gland produit le thyroxine?", listOf("Thyroïde", "Hypophyse", "Surrénale", "Pancréas"), 0, "Science", Difficulty.MEDIUM, explanation = "La thyroxine est une hormone produite par la glande thyroïde, située dans le cou. Elle régule le métabolisme du corps."),
        Question(8679, "Quel est le plus grand reef corallien du monde?", listOf("Grande Barrière de Corail", "Récif Mésoaméricain", "Récif de Belau", "Récif du Golfe Persique"), 0, "Science", Difficulty.EASY, explanation = "La Grande Barrière de Corail, située au large de l'Australie, s'étend sur plus de 2 300 kilomètres et est visible depuis l'espace."),
        Question(8680, "Quel scientifique a découvert l'argon?", listOf("William Ramsay et Morris Travers", "Henry Cavendish", "Carl Wilhelm Scheele", "Joseph Priestley"), 0, "Science", Difficulty.EXPERT, explanation = "L'argon a été découvert en 1894 par Lord Rayleigh et William Ramsay, mais Morris Travers a collaboré avec Ramsay sur d'autres gaz nobles, comme le néon."),
        Question(8681, "Quel est le symbole chimique du hafnium?", listOf("Hf", "H", "Hg", "He"), 0, "Science", Difficulty.HARD, explanation = "Le hafnium tire son symbole Hf de son nom latin Hafnium, dérivé de Hafnia, nom latin de Copenhague où il fut découvert en 1923."),
        Question(8682, "Quelle est la masse molaire de l'oxygène?", listOf("32 g/mol", "16 g/mol", "64 g/mol", "8 g/mol"), 0, "Science", Difficulty.HARD, explanation = "La molécule d'oxygène (O₂) est composée de deux atomes, chacun ayant une masse molaire de 16 g/mol, ce qui donne un total de 32 g/mol."),
        Question(8683, "Quel élément chimique est le plus électronégatif?", listOf("Fluor", "Oxygène", "Azote", "Chlore"), 0, "Science", Difficulty.HARD, explanation = "Le fluor possède la plus grande électronégativité de tous les éléments, ce qui signifie qu'il attire le plus fortement les électrons dans une liaison chimique."),
        Question(8684, "Quel scientifique a découvert le muon?", listOf("Carl Anderson", "Enrico Fermi", "Richard Feynman", "Murray Gell-Mann"), 0, "Science", Difficulty.EXPERT, explanation = "Carl Anderson a découvert le muon en 1936 en étudiant les rayons cosmiques, ce qui lui a valu le prix Nobel de physique en 1936."),
        Question(8685, "Quel est le symbole chimique du rhénium?", listOf("Re", "Rh", "Rf", "Rb"), 0, "Science", Difficulty.HARD, explanation = "Le rhénium, élément de numéro atomique 75, a pour symbole Re, dérivé de son nom latin Rhenium."),
        Question(8686, "Combien de côtés a un icosagone?", listOf("20", "10", "15", "25"), 0, "Science", Difficulty.HARD, explanation = "Le préfixe \"icosa-\" vient du grec ancien et signifie vingt, comme dans icosaèdre (vingt faces). Un icosagone est donc un polygone à vingt côtés."),
        Question(8687, "Quel gland produit la vasopressine?", listOf("Hypophyse", "Pancréas", "Thyroïde", "Surrénale"), 0, "Science", Difficulty.HARD, explanation = "L'hypophyse, ou glande pituitaire, libère la vasopressine, une hormone antidiurétique qui régule la rétention d'eau et la pression artérielle."),
        Question(8688, "Quel est le plus grand lac souterrain du monde?", listOf("Lac Don Juan", "Lac Baïkal", "Lac Caspienne", "Lac Victoria"), 0, "Science", Difficulty.EXPERT, explanation = "Le lac Don Juan, en Antarctique, est le plus grand lac souterrain du monde en volume d'eau, avec une salinité extrême qui l'empêche de geler même à -50°C."),
        Question(8689, "Quel scientifique a découvert le kaon?", listOf("Murray Gell-Mann", "George Rochester", "Buford Butler", "Alfred Pais"), 0, "Science", Difficulty.EXPERT, explanation = "Murray Gell-Mann a découvert le kaon en 1953, une particule subatomique qui a permis de développer le concept d'étrangeté en physique des particules."),
        Question(8690, "Quel est le symbole chimique du molybdène?", listOf("Mo", "Mb", "Mn", "Mg"), 0, "Science", Difficulty.HARD, explanation = "Le molybdène tire son symbole chimique Mo de son nom latin Molybdaenum. C'est un métal de transition utilisé notamment dans les alliages d'acier pour améliorer leur résistance à la chaleur."),
        Question(8691, "Quelle est la solubilité du sel dans l'eau?", listOf("36 g/100 mL", "50 g/100 mL", "20 g/100 mL", "10 g/100 mL"), 0, "Science", Difficulty.HARD, explanation = "À 20 °C, l'eau peut dissoudre au maximum 36 grammes de sel pour 100 millilitres, ce qui correspond à sa solubilité dans ces conditions standard."),
        Question(8692, "Quel élément chimique a le plus grand rayon atomique?", listOf("Francium", "Césium", "Rubidium", "Potassium"), 0, "Science", Difficulty.HARD, explanation = "Le francium possède le plus grand rayon atomique car il se situe en bas à gauche du tableau périodique, où l'ajout de couches électroniques et la faible charge nucléaire effective augmentent la taille des atomes."),
        Question(8693, "Quel scientifique a découvert le positron?", listOf("Carl Anderson", "Dirac", "Paul Diracs", "Ernest Rutherford"), 1, "Science", Difficulty.EXPERT, explanation = "Paul Dirac a prédit l'existence du positron en 1928 via son équation relativiste de l'électron, et la particule fut confirmée expérimentalement en 1932 par Carl Anderson."),
        Question(8694, "Quel est le symbole chimique du dihydrogène?", listOf("H2", "H", "He", "Ho"), 0, "Science", Difficulty.HARD, explanation = "Le symbole chimique du dihydrogène est H2 car il est composé de deux atomes d'hydrogène liés."),
        Question(8695, "Combien de vertèbres cervicales a un humain?", listOf("7", "6", "8", "5"), 0, "Science", Difficulty.HARD, explanation = "Les mammifères, y compris les humains, possèdent généralement sept vertèbres cervicales, quelle que soit la longueur de leur cou. Cette constance est une caractéristique commune à la plupart des espèces."),
        Question(8696, "Quel gland produit la somatostatine?", listOf("Pancréas", "Hypophyse", "Thyroïde", "Surrénale"), 0, "Science", Difficulty.HARD, explanation = "Le pancréas produit la somatostatine via ses cellules delta des îlots de Langerhans, une hormone qui régule la libération d'autres hormones digestives."),
        Question(8697, "Quel est le plus grand astéroïde entre Mars et Jupiter?", listOf("Cérès", "Vesta", "Pallas", "Junon"), 0, "Science", Difficulty.HARD, explanation = "Cérès est le plus grand objet de la ceinture d'astéroïdes située entre Mars et Jupiter, avec un diamètre d'environ 940 kilomètres, ce qui lui a valu d'être classé comme planète naine en 2006."),
        Question(8698, "Quel scientifique a découvert le Lambda?", listOf("Murray Gell-Mann", "George Zweig", "Buford Butler", "Robert Oppenheimer"), 0, "Science", Difficulty.EXPERT, explanation = "Murray Gell-Mann a introduit la particule lambda (Λ) dans le cadre de la classification des hadrons, qu'il a nommée la voie octuple. Ce travail lui a valu le prix Nobel de physique en 1969."),
        Question(8699, "Quel est le symbole chimique du dioxyde d'azote?", listOf("NO2", "N2O", "NO", "N2O5"), 0, "Science", Difficulty.HARD, explanation = "NO2 signifie un atome d'azote lié à deux atomes d'oxygène, formant un gaz polluant brun-rouge issu de la combustion."),
        Question(8700, "Quelle est la distance Terre-Soleil en unités astronomiques?", listOf("1 UA", "2 UA", "0.5 UA", "1.5 UA"), 0, "Science", Difficulty.MEDIUM, explanation = "L'unité astronomique (UA) est précisément définie comme la distance moyenne entre la Terre et le Soleil, soit environ 150 millions de kilomètres."),
        Question(8701, "Quel élément chimique est le troisième plus abondant dans la croûte terrestre?", listOf("Aluminium", "Fer", "Calcium", "Sodium"), 0, "Science", Difficulty.HARD, explanation = "L'aluminium est le troisième élément le plus abondant dans la croûte terrestre après l'oxygène et le silicium, représentant environ 8% de sa masse."),
        Question(8702, "Quel scientifique a découvert le Xi?", listOf("Murray Gell-Mann", "George Zweig", "Juan Carlos Santisteban", "Emilio Segrè"), 0, "Science", Difficulty.EXPERT, explanation = "Murray Gell-Mann a découvert la particule subatomique nommée Xi en 1964, contribuant à la classification des hadrons via le modèle des quarks."),
        Question(8703, "Quel est le symbole chimique du trioxyde de soufre?", listOf("SO3", "SO2", "S2O3", "SO"), 0, "Science", Difficulty.HARD, explanation = "Le trioxyde de soufre est un composé chimique de formule SO3, où S représente le soufre et O l'oxygène, avec trois atomes d'oxygène."),
        Question(8704, "Combien de cellules B a un humain environ?", listOf("1 billion", "500 millions", "100 millions", "10 billions"), 0, "Science", Difficulty.HARD, explanation = "Les lymphocytes B sont un type de globules blancs essentiels à l'immunité humorale. Le corps humain en contient environ 1 billion, soit 10¹² cellules."),
        Question(8705, "Quel gland produit l'ocytocine?", listOf("Hypophyse", "Pancréas", "Thyroïde", "Surrénale"), 0, "Science", Difficulty.HARD, explanation = "L'ocytocine est synthétisée dans l'hypothalamus, mais elle est stockée et libérée dans le sang par le lobe postérieur de l'hypophyse."),
        Question(8706, "Quel est le plus grand geyser du monde?", listOf("Steamboat Geyser", "Old Faithful", "Grand Prismatic Spring", "Pohutu Geyser"), 0, "Science", Difficulty.EXPERT, explanation = "Le Steamboat Geyser, situé dans le parc national de Yellowstone aux États-Unis, détient le record de la plus haute éruption jamais enregistrée pour un geyser, atteignant jusqu'à 90 mètres."),
        Question(8707, "Quel scientifique a découvert le photon?", listOf("Max Planck", "Albert Einstein", "Niels Bohr", "Werner Heisenberg"), 1, "Science", Difficulty.HARD, explanation = "Albert Einstein a proposé l'existence du photon en 1905 pour expliquer l'effet photoélectrique, ce qui lui a valu le prix Nobel de physique en 1921."),
        Question(8708, "Quel est le symbole chimique du monoxyde de carbone?", listOf("CO", "CO2", "C2O", "CO3"), 0, "Science", Difficulty.EASY, explanation = "Le monoxyde de carbone est un composé formé d'un atome de carbone et d'un atome d'oxygène, d'où le symbole CO."),
        Question(8709, "Quelle est la concentration de l'hémoglobine dans le sang?", listOf("15 g/100 mL", "10 g/100 mL", "20 g/100 mL", "5 g/100 mL"), 0, "Science", Difficulty.HARD, explanation = "La concentration moyenne d'hémoglobine dans le sang est d'environ 15 grammes pour 100 millilitres, variant légèrement selon le sexe et l'âge."),
        Question(8710, "Quel élément chimique est le plus mou?", listOf("Sodium", "Potassium", "Lithium", "Césium"), 0, "Science", Difficulty.HARD, explanation = "Le sodium est un métal alcalin très mou, pouvant être coupé au couteau, car ses atomes sont faiblement liés entre eux dans une structure cristalline."),
        Question(8711, "Quel scientifique a découvert le Sigma?", listOf("Murray Gell-Mann", "George Zweig", "Luis Walter Alvarez", "Jerome Friedman"), 0, "Science", Difficulty.EXPERT, explanation = "Murray Gell-Mann a introduit le concept de sigma dans le cadre de sa classification des particules subatomiques, les hadrons, en utilisant la symétrie SU(3) et le modèle des quarks."),
        Question(8712, "Quel est le symbole chimique du peroxyde d'hydrogène?", listOf("H2O2", "H2O", "HO2", "H3O2"), 0, "Science", Difficulty.MEDIUM, explanation = "H2O2 est la formule chimique du peroxyde d'hydrogène, composé de deux atomes d'hydrogène et deux atomes d'oxygène."),
        Question(8713, "Combien de lobes a le poumon gauche?", listOf("2", "3", "4", "5"), 0, "Science", Difficulty.HARD, explanation = "Le poumon gauche possède deux lobes (supérieur et inférieur) pour laisser de la place au cœur, contrairement au poumon droit qui en a trois."),
        Question(8714, "Quel gland produit la cholécystokinine?", listOf("Duodénum", "Estomac", "Foie", "Pancréas"), 0, "Science", Difficulty.HARD, explanation = "La cholécystokinine est une hormone digestive sécrétée par les cellules de la muqueuse du duodénum en réponse à l'arrivée de graisses et de protéines."),
        Question(8715, "Quel est le plus grand lac de cratère du monde?", listOf("Lac Crater", "Lac Rotoiti", "Lac Rotorua", "Lac Tanganyika"), 0, "Science", Difficulty.EXPERT, explanation = "Le lac Crater, situé dans l'Oregon aux États-Unis, s'est formé il y a environ 7 700 ans dans la caldeira du volcan Mazama. C'est le plus profond lac des États-Unis et le plus grand lac de cratère du monde par son volume."),
        Question(8716, "Quel scientifique a découvert l'antiproton?", listOf("Emilio Segrè", "Clyde Cowan", "Frederick Reines", "Luis Walter Alvarez"), 0, "Science", Difficulty.EXPERT, explanation = "Emilio Segrè a reçu le prix Nobel de physique en 1959 pour la découverte de l'antiproton, une particule d'antimatière, réalisée en 1955 avec Owen Chamberlain."),
        Question(8717, "Quel est le symbole chimique du fluorure d'hydrogène?", listOf("HF", "H2F", "HF2", "FH"), 0, "Science", Difficulty.HARD, explanation = "Le fluorure d'hydrogène est un composé chimique formé d'un atome d'hydrogène et d'un atome de fluor, d'où son symbole HF."),
        Question(8718, "Quelle est la viscosité du sang?", listOf("4-5 cP", "1-2 cP", "10-12 cP", "2-3 cP"), 0, "Science", Difficulty.HARD, explanation = "Le sang a une viscosité relative de 4 à 5 centipoises (cP) à 37°C, car il est plus épais que l'eau (1 cP) en raison des globules rouges et des protéines."),
        Question(8719, "Quel élément chimique a un électron de valence?", listOf("Sodium", "Magnésium", "Aluminium", "Silicium"), 0, "Science", Difficulty.HARD, explanation = "Le sodium possède un seul électron sur sa couche externe, ce qui en fait un élément avec un électron de valence. Cette propriété le classe dans la famille des métaux alcalins."),
        Question(8720, "Quel scientifique a découvert l'antineutrino?", listOf("Frederick Reines", "Clyde Cowan", "Luis Walter Alvarez", "Emilio Segrè"), 0, "Science", Difficulty.EXPERT, explanation = "Frederick Reines a découvert l'antineutrino en 1956 lors de l'expérience du projet Poltergeist, ce qui lui a valu le prix Nobel de physique en 1995."),
        Question(8721, "Quel est le symbole chimique du sulfure de dihydrogène?", listOf("H2S", "H2Se", "HS2", "H3S"), 0, "Science", Difficulty.HARD, explanation = "Le sulfure de dihydrogène, aussi appelé hydrogène sulfuré, est un gaz composé de deux atomes d'hydrogène et un atome de soufre, d'où son symbole chimique H2S."),
        Question(8722, "Combien de cellules T a un humain environ?", listOf("1 trillion", "500 milliards", "100 milliards", "10 trillions"), 0, "Science", Difficulty.HARD, explanation = "Le corps humain contient environ 1 trillion de lymphocytes T, un type de globule blanc essentiel au système immunitaire adaptatif. Ce nombre varie selon l'âge et l'état de santé."),
        Question(8723, "Quel gland produit le peptide intestinal vasoactif?", listOf("Duodénum", "Estomac", "Foie", "Pancréas"), 0, "Science", Difficulty.HARD, explanation = "Le peptide intestinal vasoactif est principalement sécrété par les cellules endocrines du duodénum, où il régule la vasodilatation et la motilité intestinale."),
        Question(8724, "Quel est le plus grand solfatare du monde?", listOf("Solfatara de Pouzzoles", "Geyser d'Islande", "Mud Volcanoes de Boue", "Hot Springs de Nouvelle-Zélande"), 0, "Science", Difficulty.EXPERT, explanation = "La Solfatara de Pouzzoles, près de Naples, est un cratère volcanique actif avec des fumerolles sulfureuses, ce qui en fait le plus grand solfatare du monde."),
        Question(8725, "Quel scientifique a découvert le Lambda0?", listOf("Strange et Gell-Mann", "Murray Gell-Mann", "George Zweig", "Juan Carlos Santisteban"), 0, "Science", Difficulty.EXPERT, explanation = "Le Lambda0 est une particule subatomique dont l'existence a été prédite par Murray Gell-Mann et Kazuhiko Nishijima via le concept d'étrangeté, avant sa découverte expérimentale en 1950."),
        Question(8726, "Quel est le symbole chimique de l'ammoniac?", listOf("NH3", "NH4", "NH2", "N2H4"), 0, "Science", Difficulty.MEDIUM, explanation = "NH3 est la formule chimique de l'ammoniac, composé d'un atome d'azote (N) et de trois atomes d'hydrogène (H)."),
        Question(8727, "Quelle est la concentration de l'albumine dans le plasma?", listOf("35-50 g/L", "10-20 g/L", "60-80 g/L", "80-100 g/L"), 0, "Science", Difficulty.HARD, explanation = "L'albumine est la protéine la plus abondante du plasma, synthétisée par le foie, et sa concentration normale se situe entre 35 et 50 g/L, jouant un rôle clé dans le maintien de la pression oncotique."),
        Question(8728, "Quel élément chimique a deux électrons de valence?", listOf("Magnésium", "Sodium", "Aluminium", "Silicium"), 0, "Science", Difficulty.HARD, explanation = "Le magnésium, situé dans la deuxième colonne du tableau périodique, possède deux électrons de valence dans sa couche externe."),
        Question(8729, "Quel scientifique a découvert le graviton?", listOf("Théorique", "Albert Einstein", "Max Planck", "Werner Heisenberg"), 0, "Science", Difficulty.EXPERT, explanation = "Le graviton est une particule hypothétique prédite par la théorie quantique des champs, mais son existence n'a pas été observée expérimentalement, ce qui en fait un concept purement théorique."),
        Question(8730, "Quel est le symbole chimique du cyanure d'hydrogène?", listOf("HCN", "H2CN", "HCEN", "HCN2"), 0, "Science", Difficulty.HARD, explanation = "Le cyanure d'hydrogène est un composé chimique de formule HCN, où H représente l'hydrogène, C le carbone et N l'azote. Ce gaz incolore et hautement toxique est utilisé dans certains procédés industriels."),
        Question(8731, "Combien de vertèbres thoraciques a un humain?", listOf("12", "11", "13", "10"), 0, "Science", Difficulty.HARD, explanation = "La colonne vertébrale humaine compte 12 vertèbres thoraciques, situées entre les vertèbres cervicales et lombaires, chacune s'articulant avec une paire de côtes."),
        Question(8732, "Quel gland produit la gastrine?", listOf("Estomac", "Duodénum", "Pancréas", "Foie"), 0, "Science", Difficulty.HARD, explanation = "La gastrine est une hormone produite par les cellules G de l'estomac, qui stimule la sécrétion d'acide gastrique."),
        Question(8733, "Quel est le plus grand polder du monde?", listOf("Polder d'Afsluitdijk", "Polder de Flevoland", "Polder de Haringvliet", "Polder de Wieringermeer"), 0, "Science", Difficulty.EXPERT, explanation = "Le polder d'Afsluitdijk aux Pays-Bas est le plus grand du monde, créé après la construction de la digée fermant le Zuiderzee en 1932."),
        Question(8734, "Quel scientifique a théorisé les cordes cosmiques?", listOf("Tom Kibble", "Stephen Hawking", "Paul Dirac", "Dirac"), 0, "Science", Difficulty.EXPERT, explanation = "Tom Kibble a proposé le concept de cordes cosmiques dans les années 1970, en lien avec les transitions de phase dans l'univers primordial."),
        Question(8735, "Quel est le symbole chimique du méthanal?", listOf("CH2O", "CH3O", "CHO", "CH4O"), 0, "Science", Difficulty.HARD, explanation = "Le méthanal, aussi appelé formaldéhyde, est un aldéhyde dont la molécule contient un atome de carbone, deux d'hydrogène et un d'oxygène, d'où le symbole CH2O."),
        Question(8736, "Quelle est la pression osmotique du plasma sanguin?", listOf("7.7 atm", "5 atm", "10 atm", "3 atm"), 0, "Science", Difficulty.HARD, explanation = "La pression osmotique du plasma sanguin est d'environ 7,7 atmosphères, valeur qui correspond à l'équilibre des échanges d'eau entre le sang et les tissus."),
        Question(8737, "Quel élément chimique a trois électrons de valence?", listOf("Aluminium", "Sodium", "Magnésium", "Silicium"), 0, "Science", Difficulty.HARD, explanation = "L'aluminium, situé dans le groupe 13 du tableau périodique, possède trois électrons dans sa couche de valence, ce qui lui confère une valence de +3."),
        Question(8738, "Quel scientifique a découvert la violation de parité?", listOf("Chien-Shiung Wu", "Tsung-Dao Lee", "Chen Ning Yang", "Wolfgang Pauli"), 0, "Science", Difficulty.EXPERT, explanation = "Chien-Shiung Wu a prouvé expérimentalement en 1956 que la loi de conservation de la parité était violée dans les interactions faibles, contredisant une croyance fondamentale en physique."),
        Question(8739, "Quel est le symbole chimique de l'éthanal?", listOf("CH3CHO", "CH3CH2OH", "CH3COCH3", "CH3CHO2"), 0, "Science", Difficulty.HARD, explanation = "Le symbole CH3CHO représente la formule semi-développée de l'éthanal, un aldéhyde à deux carbones, où le groupe fonctionnel -CHO est caractéristique."),
        Question(8740, "Combien de vertèbres lombaires a un humain?", listOf("5", "4", "6", "3"), 0, "Science", Difficulty.HARD, explanation = "La colonne vertébrale humaine compte cinq vertèbres lombaires, situées entre les vertèbres thoraciques et le sacrum, assurant soutien et flexibilité du bas du dos."),
        Question(8741, "Quel gland produit la secretine?", listOf("Duodénum", "Estomac", "Pancréas", "Foie"), 0, "Science", Difficulty.HARD, explanation = "La sécrétine est une hormone produite par les cellules S du duodénum en réponse à l'acidité du chyme gastrique, stimulant la sécrétion de bicarbonate par le pancréas."),
        Question(8742, "Quel est le plus grand esker du monde?", listOf("Oak Ridges Moraine", "Vitosha", "Porfyrjöskull", "Salpausselkä"), 0, "Science", Difficulty.EXPERT, explanation = "L'esker d'Oak Ridges Moraine, situé en Ontario au Canada, est le plus long esker connu au monde, s'étendant sur environ 200 kilomètres."),
        Question(8743, "Quel scientifique a découvert la résonance magnétique?", listOf("Isidor Rabi", "Richard Feynman", "Julian Schwinger", "Sin-Itiro Tomonaga"), 0, "Science", Difficulty.EXPERT, explanation = "Isidor Rabi a reçu le prix Nobel de physique en 1944 pour sa découverte de la résonance magnétique nucléaire, une méthode qui utilise des champs magnétiques pour sonder les propriétés des noyaux atomiques."),
        Question(8744, "Quel est le symbole chimique de l'acide acétique?", listOf("CH3COOH", "CH3COH", "CH3CO2", "CH3COOH2"), 0, "Science", Difficulty.HARD, explanation = "CH3COOH est la formule semi-développée de l'acide acétique, le principal composant du vinaigre."),
        Question(8745, "Quelle est la concentration de la glucose dans le plasma?", listOf("70-100 mg/100 mL", "100-120 mg/100 mL", "50-70 mg/100 mL", "120-140 mg/100 mL"), 0, "Science", Difficulty.HARD, explanation = "La glycémie à jeun normale se situe entre 70 et 100 mg/100 mL de plasma, un équilibre maintenu par l'insuline et le glucagon."),
        Question(8746, "Quel élément chimique a quatre électrons de valence?", listOf("Carbone", "Sodium", "Magnésium", "Aluminium"), 0, "Science", Difficulty.HARD, explanation = "Le carbone possède quatre électrons de valence, ce qui lui permet de former quatre liaisons covalentes, une propriété essentielle pour la diversité des molécules organiques."),
        Question(8747, "Quel scientifique a découvert l'électrodynamique quantique?", listOf("Richard Feynman", "Julian Schwinger", "Sin-Itiro Tomonaga", "Freeman Dyson"), 0, "Science", Difficulty.EXPERT, explanation = "Richard Feynman a formulé l'électrodynamique quantique dans les années 1940, une théorie qui décrit l'interaction entre la lumière et la matière."),
        Question(8748, "Quel est le symbole chimique de l'acétone?", listOf("CH3COCH3", "CH3CHO", "CH3CH2OH", "CH3CH2CHO"), 0, "Science", Difficulty.HARD, explanation = "L'acétone est un composé organique de formule chimique CH3COCH3, où le groupe carbonyle (C=O) est lié à deux groupes méthyle (CH3). Ce symbole représente sa structure moléculaire précise."),
        Question(8749, "Combien de vertèbres sacrées a un humain?", listOf("5", "4", "6", "3"), 0, "Science", Difficulty.HARD, explanation = "Le sacrum humain est formé par la fusion de cinq vertèbres sacrées, un nombre constant chez l'adulte. Cette fusion se produit généralement entre 18 et 30 ans."),
        Question(8750, "Quel gland produit la motiline?", listOf("Duodénum", "Estomac", "Pancréas", "Foie"), 0, "Science", Difficulty.HARD, explanation = "La motiline est une hormone produite par les cellules entérochromaffines du duodénum, qui régule la motilité intestinale en stimulant les contractions de l'estomac et de l'intestin grêle."),
        Question(8751, "Quel est le plus grand kame du monde?", listOf("Kame d'Islande", "Kame du Yellowstone", "Kame du Kamchatka", "Kame de Nouvelle-Zélande"), 0, "Science", Difficulty.EXPERT, explanation = "Le plus grand kame du monde est le Kame d'Islande, une formation géologique de glace et de roche située en Islande, mesurant environ 10 kilomètres de long."),
        Question(8752, "Quel scientifique a découvert la théorie des champs?", listOf("Paul Dirac", "Albert Einstein", "Max Planck", "Werner Heisenberg"), 0, "Science", Difficulty.EXPERT, explanation = "Paul Dirac a formulé la théorie quantique des champs dans les années 1920, unifiant la mécanique quantique et la relativité restreinte pour décrire les particules et leurs interactions."),
        Question(8753, "Quel est le symbole chimique du benzène?", listOf("C6H6", "C6H5", "C6H8", "C6H4"), 0, "Science", Difficulty.HARD, explanation = "Le benzène est un hydrocarbure aromatique composé de six atomes de carbone et six atomes d'hydrogène, d'où sa formule chimique C6H6."),
        Question(8754, "Quelle est la concentration du potassium dans le plasma?", listOf("3.5-5 mEq/L", "1-2 mEq/L", "7-8 mEq/L", "10-12 mEq/L"), 0, "Science", Difficulty.HARD, explanation = "Le potassium plasmatique est maintenu dans cette étroite fourchette par les reins et les hormones, car des écarts peuvent perturber l'activité électrique du cœur et des nerfs."),
        Question(8755, "Quel élément chimique a cinq électrons de valence?", listOf("Azote", "Carbone", "Oxygène", "Phosphore"), 0, "Science", Difficulty.HARD, explanation = "L'azote, situé dans le groupe 15 du tableau périodique, possède cinq électrons dans sa couche de valence, ce qui lui permet de former trois liaisons covalentes pour atteindre l'octet."),
        Question(8756, "Quel scientifique a découvert la non-localité?", listOf("John Bell", "Albert Einstein", "Niels Bohr", "David Bohm"), 0, "Science", Difficulty.EXPERT, explanation = "John Bell a démontré en 1964 que la mécanique quantique prédit des corrélations non locales, via son théorème et ses inégalités."),
        Question(8757, "Quel est le symbole chimique du phénol?", listOf("C6H5OH", "C6H6", "C6H4OH", "C6H3OH"), 0, "Science", Difficulty.HARD, explanation = "Le phénol est un composé aromatique constitué d'un noyau benzénique (C6H5) lié à un groupe hydroxyle (OH), d'où sa formule chimique C6H5OH."),
        Question(8758, "Combien de côtes sternales a un humain?", listOf("7", "6", "8", "5"), 0, "Science", Difficulty.HARD, explanation = "L'humain possède 7 paires de côtes sternales, aussi appelées vraies côtes, car elles sont directement reliées au sternum par leur propre cartilage costal."),
        Question(8759, "Quel gland produit la cholécystokinine?", listOf("Duodénum", "Estomac", "Pancréas", "Foie"), 1, "Science", Difficulty.HARD, explanation = "La cholécystokinine est une hormone digestive principalement sécrétée par les cellules de la muqueuse de l'estomac, ainsi que par l'intestin grêle."),
        Question(8760, "Quel est le plus grand cône de scories du monde?", listOf("Cinder Cone", "Sunset Crater", "Spatter Cone", "Lava Dome"), 0, "Science", Difficulty.EXPERT, explanation = "Le Cinder Cone, situé dans le parc national de Lassen Volcanic en Californie, est le plus grand cône de scories du monde avec une hauteur d'environ 210 mètres."),
        Question(8761, "Quel scientifique a découvert la mécanique statistique?", listOf("Ludwig Boltzmann", "J. Willard Gibbs", "Josiah Willard Gibbs", "Paul Ehrenfest"), 0, "Science", Difficulty.EXPERT, explanation = "Ludwig Boltzmann a fondé la mécanique statistique en reliant les propriétés macroscopiques des gaz au comportement des atomes et molécules, formalisant ainsi le lien entre thermodynamique et physique microscopique."),
        Question(8762, "Quel est le symbole chimique du toluène?", listOf("C6H5CH3", "C6H6", "C7H8", "C6H4CH3"), 0, "Science", Difficulty.HARD, explanation = "Le toluène est un hydrocarbure aromatique de formule C6H5CH3, dérivé du benzène par substitution d'un atome d'hydrogène par un groupe méthyle."),
        Question(8763, "Quelle est la concentration du calcium dans le plasma?", listOf("8.5-10.5 mg/100 mL", "5-7 mg/100 mL", "12-14 mg/100 mL", "15-17 mg/100 mL"), 0, "Science", Difficulty.HARD, explanation = "Le taux de calcium plasmatique est maintenu dans cette plage étroite par les hormones parathyroïdiennes et la vitamine D, essentiel pour les fonctions nerveuses et musculaires."),
        Question(8764, "Quel élément chimique a six électrons de valence?", listOf("Oxygène", "Azote", "Carbone", "Soufre"), 0, "Science", Difficulty.HARD, explanation = "L'oxygène est dans le groupe 16 du tableau périodique, ce qui lui donne six électrons de valence dans sa couche externe."),
        Question(8765, "Quel scientifique a découvert la renormalisation?", listOf("Richard Feynman", "Julian Schwinger", "Sin-Itiro Tomonaga", "Freeman Dyson"), 0, "Science", Difficulty.EXPERT, explanation = "Richard Feynman a contribué au développement de la renormalisation en électrodynamique quantique, une technique mathématique permettant d'éliminer les infinis dans les calculs théoriques."),
        Question(8766, "Quel est le symbole chimique du styrène?", listOf("C6H5CH=CH2", "C6H6", "C8H8", "C6H4CH=CH2"), 0, "Science", Difficulty.HARD, explanation = "Le styrène est un composé organique de formule brute C8H8, souvent représenté par C6H5CH=CH2 pour montrer son groupe phényle lié à un groupe vinyle."),
        Question(8767, "Combien de paires de côtes flottantes a un humain?", listOf("2", "3", "1", "4"), 0, "Science", Difficulty.HARD, explanation = "L'humain possède 12 paires de côtes, dont les deux dernières (paires 11 et 12) sont dites flottantes car elles ne sont pas reliées au sternum."),
        Question(8768, "Quel gland produit l'enteroglucagon?", listOf("Duodénum", "Estomac", "Pancréas", "Foie"), 0, "Science", Difficulty.HARD, explanation = "L'entéroglucagon est une hormone sécrétée par les cellules L de l'intestin grêle, principalement localisées dans le duodénum."),
        Question(8769, "Quel est le plus grand stratovolcan du monde?", listOf("Ojos del Salado", "Mont Piton", "Mont Fuji", "Mont Merapi"), 0, "Science", Difficulty.HARD, explanation = "Le volcan Ojos del Salado, situé à la frontière entre le Chili et l'Argentine, culmine à 6 893 mètres d'altitude, ce qui en fait le plus haut stratovolcan actif du monde."),
        Question(8770, "Quel scientifique a découvert le calcul des variations?", listOf("Leonhard Euler", "Isaac Newton", "Gottfried Leibniz", "Johann Bernoulli"), 0, "Science", Difficulty.EXPERT, explanation = "Leonhard Euler a posé les fondements du calcul des variations au XVIIIe siècle, notamment avec l'équation d'Euler-Lagrange, formalisant la recherche de fonctions qui minimisent ou maximisent des intégrales."),
        Question(8771, "Quel est le symbole chimique du xylène?", listOf("C6H4(CH3)2", "C6H6", "C8H10", "C6H4CH3"), 0, "Science", Difficulty.HARD, explanation = "Le xylène est un hydrocarbure aromatique de formule brute C8H10, souvent représenté par C6H4(CH3)2 pour indiquer un noyau benzénique avec deux groupes méthyle."),
        Question(8772, "Quelle est la concentration du sodium dans le plasma?", listOf("135-145 mEq/L", "120-130 mEq/L", "150-160 mEq/L", "100-110 mEq/L"), 0, "Science", Difficulty.HARD, explanation = "Le sodium est le principal cation du milieu extracellulaire et sa concentration plasmatique normale est maintenue entre 135 et 145 mEq/L par les reins et les hormones."),
        Question(8773, "Quel élément chimique a sept électrons de valence?", listOf("Chlore", "Azote", "Oxygène", "Fluor"), 0, "Science", Difficulty.HARD, explanation = "Le chlore appartient à la famille des halogènes (groupe 17), ce qui lui confère sept électrons de valence dans sa couche externe."),
        Question(8774, "Quel scientifique a découvert les nombres de Stirling?", listOf("James Stirling", "Isaac Newton", "Leonhard Euler", "Gottfried Leibniz"), 0, "Science", Difficulty.EXPERT, explanation = "James Stirling, mathématicien écossais du XVIIIe siècle, a introduit ces nombres dans son ouvrage *Methodus Differentialis* pour l'étude des séries et des permutations."),
        Question(8775, "Quel est le symbole chimique du naphthalène?", listOf("C10H8", "C10H6", "C12H8", "C10H10"), 0, "Science", Difficulty.HARD, explanation = "Le naphthalène est un hydrocarbure aromatique composé de 10 atomes de carbone et 8 atomes d'hydrogène, d'où sa formule brute C10H8, souvent utilisée comme symbole chimique."),
        Question(8776, "Combien de paires de côtes vraies a un humain?", listOf("7", "8", "6", "9"), 0, "Science", Difficulty.HARD, explanation = "Les 7 premières paires de côtes sont dites vraies car elles sont directement reliées au sternum par leur propre cartilage costal."),
        Question(8777, "Quel gland produit le peptide YY?", listOf("Duodénum", "Estomac", "Pancréas", "Foie"), 0, "Science", Difficulty.HARD, explanation = "Le peptide YY est une hormone sécrétée par les cellules L du duodénum et de l'iléon, principalement en réponse à l'ingestion de nutriments."),
        Question(8778, "Quel est le plus grand tableau ou tableau de llave du monde?", listOf("Khara-Khoto", "Petra", "Mesa Verde", "Chaco Canyon"), 0, "Science", Difficulty.EXPERT, explanation = "Khara-Khoto est une ancienne cité fortifiée de la route de la soie en Mongolie-Intérieure, et son nom signifie \"ville noire\" en mongol."),
        Question(8779, "Quel scientifique a découvert l'algèbre linéaire?", listOf("Arthur Cayley", "Isaac Newton", "Leonhard Euler", "Augustin-Louis Cauchy"), 0, "Science", Difficulty.EXPERT, explanation = "Arthur Cayley a formalisé l'algèbre linéaire au XIXe siècle en développant la théorie des matrices et des déterminants, posant ainsi les bases de cette branche mathématique."),
        Question(8780, "Quel est le symbole chimique de l'anthracène?", listOf("C14H10", "C14H8", "C16H10", "C14H12"), 0, "Science", Difficulty.HARD, explanation = "L'anthracène est un hydrocarbure aromatique polycyclique composé de 14 atomes de carbone et 10 atomes d'hydrogène, d'où sa formule brute C14H10."),
        Question(8781, "Quelle est la concentration du magnésium dans le plasma?", listOf("1.7-2.2 mg/100 mL", "1-1.5 mg/100 mL", "3-3.5 mg/100 mL", "4-4.5 mg/100 mL"), 0, "Science", Difficulty.HARD, explanation = "La concentration plasmatique de magnésium est normalement comprise entre 1,7 et 2,2 mg/100 mL, car ce minéral est essentiel à de nombreuses réactions enzymatiques et à la fonction neuromusculaire."),
        Question(8782, "Quel élément chimique a huit électrons de valence?", listOf("Oxygène", "Azote", "Carbone", "Néon"), 0, "Science", Difficulty.HARD, explanation = "L'oxygène est dans la seizième colonne du tableau périodique, ce qui lui donne six électrons de valence, et non huit. L'élément avec huit électrons de valence est un gaz noble comme le néon ou l'argon."),
        Question(8783, "Quel scientifique a découvert la géométrie projective?", listOf("Gérard Desargues", "René Descartes", "Blaise Pascal", "Pierre de Fermat"), 0, "Science", Difficulty.EXPERT, explanation = "Gérard Desargues, mathématicien et architecte français du XVIIe siècle, a posé les bases de la géométrie projective en étudiant les propriétés des figures qui restent invariantes par projection."),
        Question(8784, "Quel est le symbole chimique du pyrène?", listOf("C16H10", "C16H8", "C18H10", "C16H12"), 0, "Science", Difficulty.HARD, explanation = "Le pyrène est un hydrocarbure aromatique polycyclique composé de 16 atomes de carbone et 10 atomes d'hydrogène, d'où sa formule brute C16H10."),
        Question(8785, "Combien de côtes asternales a un humain?", listOf("2", "1", "3", "4"), 0, "Science", Difficulty.HARD, explanation = "Les côtes asternales, aussi appelées côtes flottantes, sont les deux dernières paires de côtes qui ne sont pas reliées au sternum. Chez l'humain, il y en a donc deux de chaque côté, soit quatre au total, mais la question se réfère souvent au nombre par côté."),
        Question(8786, "Quel gland produit le GLP-1?", listOf("Duodénum", "Estomac", "Pancréas", "Foie"), 0, "Science", Difficulty.HARD, explanation = "Le GLP-1 est une hormone incrétine sécrétée principalement par les cellules L de l'intestin grêle, notamment dans le duodénum, en réponse à l'ingestion de nutriments."),
        Question(8787, "Quel est le plus grand tumuli du monde?", listOf("Cahokia Mounds", "Monks Mound", "Serpent Mound", "Grave Creek Mound"), 0, "Science", Difficulty.EXPERT, explanation = "Situé dans l'Illinois, le site de Cahokia Mounds abrite le Monks Mound, un tumulus de terre haut de 30 mètres, le plus grand des Amériques et du monde."),
        Question(8788, "Quel scientifique a découvert les nombres complexes?", listOf("Carl Friedrich Gauss", "Isaac Newton", "Leonhard Euler", "Gottfried Leibniz"), 0, "Science", Difficulty.EXPERT, explanation = "Bien que d'autres mathématiciens comme Cardan aient manipulé des racines de nombres négatifs, c'est Gauss qui a formalisé leur représentation géométrique et leur a donné une légitimité mathématique au XIXe siècle."),
        Question(8789, "Quel est le symbole chimique du chrysène?", listOf("C18H12", "C18H10", "C20H12", "C18H14"), 0, "Science", Difficulty.HARD, explanation = "Le chrysène est un hydrocarbure aromatique polycyclique composé de 18 atomes de carbone et 12 atomes d'hydrogène, d'où sa formule brute C18H12."),
        Question(8790, "Quelle est la concentration du phosphore dans le plasma?", listOf("2.5-4.5 mg/100 mL", "1-2 mg/100 mL", "5-6 mg/100 mL", "7-8 mg/100 mL"), 0, "Science", Difficulty.HARD, explanation = "Le phosphore plasmatique est principalement présent sous forme d'ions phosphate inorganiques, essentiels au métabolisme osseux et énergétique, avec une concentration normale comprise entre 2,5 et 4,5 mg/100 mL."),
        Question(8791, "Quel élément chimique est un halogène?", listOf("Iode", "Carbone", "Soufre", "Azote"), 0, "Science", Difficulty.MEDIUM, explanation = "L'iode fait partie de la famille des halogènes, qui comprend également le fluor, le chlore et le brome, située dans la 17e colonne du tableau périodique."),
        Question(8792, "Quel scientifique a découvert la décomposition en fractions partielles?", listOf("Gottfried Leibniz", "Isaac Newton", "Leonhard Euler", "Johann Bernoulli"), 0, "Science", Difficulty.EXPERT, explanation = "Gottfried Leibniz a introduit la méthode de décomposition en fractions partielles au XVIIe siècle dans le cadre de ses travaux sur le calcul intégral, permettant de simplifier l'intégration de fonctions rationnelles."),
        Question(8793, "Quel est le symbole chimique du benzo[a]pyrène?", listOf("C20H12", "C20H10", "C22H12", "C20H14"), 0, "Science", Difficulty.HARD, explanation = "Le benzo[a]pyrène est un hydrocarbure aromatique polycyclique composé de 20 atomes de carbone et 12 d'hydrogène, d'où sa formule chimique C20H12."),
        Question(8794, "Combien de cellules ganglionnaires a la rétine?", listOf("1 million", "500000", "2 millions", "5 millions"), 0, "Science", Difficulty.HARD, explanation = "La rétine humaine contient environ 1 million de cellules ganglionnaires, qui transmettent les signaux visuels des photorécepteurs au cerveau via le nerf optique."),
        Question(8795, "Quel gland produit la ghréline?", listOf("Estomac", "Pancréas", "Duodénum", "Foie"), 0, "Science", Difficulty.HARD, explanation = "La ghréline, souvent appelée hormone de la faim, est principalement sécrétée par les cellules de l'estomac pour signaler la sensation de faim au cerveau."),
        Question(8796, "Quel est le plus grand dolmen du monde?", listOf("Dolmen de Bagneux", "Dolmen de la Pierre de Couverture", "Dolmen d'Agius", "Dolmen de Newgrange"), 0, "Science", Difficulty.EXPERT, explanation = "Le Dolmen de Bagneux, situé à Saumur en France, est le plus grand dolmen d'Europe avec une table de couverture pesant environ 86 tonnes."),
        Question(8797, "Quel scientifique a découvert la théorie des ensembles?", listOf("Georg Cantor", "Isaac Newton", "Leonhard Euler", "Augustin-Louis Cauchy"), 0, "Science", Difficulty.EXPERT, explanation = "Georg Cantor a développé la théorie des ensembles à la fin du XIXe siècle, révolutionnant les mathématiques en formalisant les concepts d'infini et de cardinalité."),
        Question(8798, "Quel est le symbole chimique du triphenylène?", listOf("C18H12", "C18H10", "C20H12", "C18H14"), 0, "Science", Difficulty.HARD, explanation = "Le triphenylène est un hydrocarbure aromatique polycyclique composé de 18 atomes de carbone et 12 d'hydrogène, d'où sa formule brute C18H12."),
        Question(8799, "Quelle est la concentration du cholestérol dans le plasma?", listOf("150-250 mg/100 mL", "100-150 mg/100 mL", "250-350 mg/100 mL", "50-100 mg/100 mL"), 0, "Science", Difficulty.HARD, explanation = "Le cholestérol plasmatique est normalement compris entre 150 et 250 mg/100 mL, car il est essentiel aux membranes cellulaires et à la synthèse hormonale, mais un taux élevé augmente les risques cardiovasculaires."),
        Question(8800, "Quel élément chimique est un gaz inerte?", listOf("Argon", "Carbone", "Soufre", "Azote"), 0, "Science", Difficulty.EASY, explanation = "L'argon est un gaz rare ou inerte car il ne réagit pratiquement pas chimiquement, étant stable avec une couche électronique complète. Il fait partie du groupe des gaz nobles."),
        Question(8801, "Quel scientifique a découvert le calcul vectoriel?", listOf("Oliver Heaviside", "Isaac Newton", "Leonhard Euler", "Augustin-Louis Cauchy"), 0, "Science", Difficulty.EXPERT, explanation = "Oliver Heaviside, ingénieur et physicien britannique, a reformulé les équations de Maxwell et développé le calcul vectoriel moderne dans les années 1880."),
        Question(8802, "Quel est le symbole chimique du 1,4-benzoquinone?", listOf("C6H4O2", "C6H4O", "C6H6O2", "C6H4O3"), 0, "Science", Difficulty.HARD, explanation = "Le 1,4-benzoquinone, aussi appelé para-benzoquinone, a pour formule brute C6H4O2, indiquant six atomes de carbone, quatre d'hydrogène et deux d'oxygène. C'est un composé organique utilisé notamment comme oxydant en chimie."),
        Question(8803, "Combien de cônes rétiniens a l'œil humain?", listOf("6-7 millions", "3-4 millions", "10-11 millions", "1-2 millions"), 0, "Science", Difficulty.HARD, explanation = "L'œil humain contient environ 6 à 7 millions de cônes, principalement concentrés dans la fovéa, permettant la vision des couleurs et des détails fins."),
        Question(8804, "Quel gland produit la leptine?", listOf("Tissu adipeux", "Pancréas", "Estomac", "Foie"), 0, "Science", Difficulty.HARD, explanation = "La leptine est une hormone produite principalement par les cellules adipeuses (tissu adipeux) pour réguler l'appétit et le métabolisme énergétique."),
        Question(8805, "Quel est le plus grand monument datant de la préhistoire?", listOf("Stonehenge", "Les Pyramides", "Angkor Wat", "Machu Picchu"), 0, "Science", Difficulty.EASY, explanation = "Stonehenge, en Angleterre, est le plus célèbre monument mégalithique préhistorique, construit entre 3000 et 2000 av. J.-C."),
        Question(8806, "Quel scientifique a découvert l'analyse tensorielle?", listOf("Gregorio Ricci-Curbastro", "Isaac Newton", "Leonhard Euler", "Augustin-Louis Cauchy"), 0, "Science", Difficulty.EXPERT, explanation = "Gregorio Ricci-Curbastro, mathématicien italien, a développé le calcul tensoriel à la fin du XIXe siècle, avec son élève Tullio Levi-Civita. Cette théorie est devenue un outil fondamental pour la relativité générale d'Einstein."),
        Question(8807, "Quel est le symbole chimique du phénylamine?", listOf("C6H5NH2", "C6H5NH", "C6H5N", "C6H4NH2"), 0, "Science", Difficulty.HARD, explanation = "Le phénylamine, aussi appelée aniline, a pour formule chimique C6H5NH2, où C6H5 représente le cycle benzénique et NH2 le groupe amine."),
        Question(8808, "Quelle est la concentration des triglycérides dans le plasma?", listOf("50-200 mg/100 mL", "20-50 mg/100 mL", "200-300 mg/100 mL", "300-400 mg/100 mL"), 0, "Science", Difficulty.HARD, explanation = "Les triglycérides sont des lipides circulant dans le sang, et leur concentration normale à jeun se situe entre 50 et 200 mg/100 mL, au-delà de laquelle on parle d'hypertriglycéridémie."),
        Question(8809, "Quel élément chimique a deux valences?", listOf("Cuivre", "Sodium", "Aluminium", "Carbone"), 0, "Science", Difficulty.HARD, explanation = "Le cuivre possède deux valences principales : +1 (cuivreux) et +2 (cuivrique), ce qui lui permet de former deux types de composés chimiques distincts."),
        Question(8810, "Quel scientifique a découvert le théorème de Stokes?", listOf("George Gabriel Stokes", "Isaac Newton", "Leonhard Euler", "Augustin-Louis Cauchy"), 0, "Science", Difficulty.EXPERT, explanation = "George Gabriel Stokes, mathématicien et physicien irlandais du XIXe siècle, a formulé ce théorème fondamental en analyse vectorielle, reliant l'intégrale de surface d'un champ vectoriel à son intégrale curviligne."),
        Question(8811, "Quel est le symbole chimique du toluène?", listOf("C6H5CH3", "C6H6", "C7H8", "C6H4CH3"), 1, "Science", Difficulty.HARD, explanation = "Le toluène est un hydrocarbure aromatique de formule C7H8, pas C6H6. Le benzène a pour formule C6H6."),
        Question(8812, "Combien de bâtonnets rétiniens a l'œil humain?", listOf("120-130 millions", "60-70 millions", "150-160 millions", "30-40 millions"), 0, "Science", Difficulty.HARD, explanation = "Les bâtonnets sont les photorécepteurs responsables de la vision en basse lumière, et leur nombre, estimé entre 120 et 130 millions, dépasse largement celui des cônes (environ 6 millions)."),
        Question(8813, "Quel gland produit l'adiponectine?", listOf("Tissu adipeux", "Pancréas", "Estomac", "Foie"), 0, "Science", Difficulty.HARD, explanation = "L'adiponectine est une hormone sécrétée principalement par les cellules du tissu adipeux, qui régule le métabolisme du glucose et des acides gras."),
        Question(8814, "Quel est le plus grand site archéologique connu?", listOf("Angkor", "Les Pyramides", "Pompéi", "Pétra"), 0, "Science", Difficulty.EXPERT, explanation = "Angkor, au Cambodge, est considéré comme le plus grand site archéologique au monde, s'étendant sur environ 400 km². Il abrite les vestiges de l'empire khmer, incluant le célèbre temple d'Angkor Vat."),
        Question(8815, "Quel scientifique a découvert le théorème de Green?", listOf("George Green", "Isaac Newton", "Leonhard Euler", "Augustin-Louis Cauchy"), 0, "Science", Difficulty.EXPERT, explanation = "George Green, mathématicien et physicien britannique autodidacte, a formulé ce théorème en 1828 dans son essai sur l'analyse mathématique des phénomènes électriques et magnétiques."),
        Question(8816, "Quel est le symbole chimique du para-xylène?", listOf("C6H4(CH3)2", "C6H6", "C8H10", "C6H4CH3"), 0, "Science", Difficulty.HARD, explanation = "Le para-xylène est un hydrocarbure aromatique de formule C8H10, souvent représenté par C6H4(CH3)2 pour indiquer deux groupes méthyle attachés à un cycle benzénique en position para."),
        Question(8817, "Quelle est la concentration de l'urée dans le plasma?", listOf("20-35 mg/100 mL", "10-20 mg/100 mL", "40-50 mg/100 mL", "50-60 mg/100 mL"), 0, "Science", Difficulty.HARD, explanation = "L'urée est le principal déchet azoté du métabolisme des protéines, filtrée par les reins. Sa concentration plasmatique normale se situe entre 20 et 35 mg/100 mL, reflétant l'équilibre entre production hépatique et excrétion rénale."),
        Question(8818, "Quel élément chimique a trois valences?", listOf("Aluminium", "Sodium", "Magnésium", "Carbone"), 0, "Science", Difficulty.HARD, explanation = "L'aluminium a trois électrons de valence dans sa couche externe, ce qui lui permet de former trois liaisons chimiques, comme dans l'oxyde d'aluminium Al2O3."),
        Question(8819, "Quel scientifique a découvert le théorème de Gauss?", listOf("Carl Friedrich Gauss", "Isaac Newton", "Leonhard Euler", "Augustin-Louis Cauchy"), 0, "Science", Difficulty.EXPERT, explanation = "Carl Friedrich Gauss, mathématicien allemand du XIXe siècle, a énoncé ce théorème fondamental en algèbre et en analyse, notamment le théorème fondamental de l'algèbre et le théorème de Gauss en électromagnétisme."),
        Question(8820, "Quel est le symbole chimique du méta-xylène?", listOf("C6H4(CH3)2", "C6H6", "C8H10", "C6H4CH3"), 0, "Science", Difficulty.HARD, explanation = "Le méta-xylène est un hydrocarbure aromatique de formule C6H4(CH3)2, où deux groupes méthyle sont fixés sur un noyau benzénique en position méta."),
        Question(8821, "Combien de fibres optiques a le nerf optique?", listOf("1 million", "500000", "2 millions", "5 millions"), 0, "Science", Difficulty.HARD, explanation = "Le nerf optique humain contient environ 1 million de fibres nerveuses, chacune transmettant des signaux visuels de la rétine au cerveau."),
        Question(8822, "Quel gland produit la résistine?", listOf("Tissu adipeux", "Pancréas", "Estomac", "Foie"), 0, "Science", Difficulty.HARD, explanation = "La résistine est une hormone sécrétée principalement par le tissu adipeux, jouant un rôle dans la régulation du métabolisme glucidique et l'insulinorésistance."),
        Question(8823, "Quel est le plus grand site urbain antique?", listOf("Rome", "Athènes", "Babylone", "Alexandrie"), 0, "Science", Difficulty.HARD, explanation = "Rome était la capitale de l'Empire romain, atteignant une population d'environ un million d'habitants à son apogée, ce qui en fait la plus grande ville de l'Antiquité."),
        Question(8824, "Quel scientifique a découvert le théorème d'Ampère?", listOf("André-Marie Ampère", "Michael Faraday", "Carl Friedrich Gauss", "Isaac Newton"), 0, "Science", Difficulty.EXPERT, explanation = "André-Marie Ampère a formulé ce théorème fondamental de l'électromagnétisme dans les années 1820, reliant le champ magnétique au courant électrique qui le produit."),
        Question(8825, "Quel est le symbole chimique de l'ortho-xylène?", listOf("C6H4(CH3)2", "C6H6", "C8H10", "C6H4CH3"), 0, "Science", Difficulty.HARD, explanation = "L'ortho-xylène est un hydrocarbure aromatique de formule C6H4(CH3)2, où les deux groupes méthyle sont adjacents sur le cycle benzénique. Ce symbole chimique représente sa structure moléculaire spécifique."),
        Question(8826, "Quelle est la concentration de l'acide urique dans le plasma?", listOf("3-7 mg/100 mL", "1-3 mg/100 mL", "8-10 mg/100 mL", "10-12 mg/100 mL"), 0, "Science", Difficulty.HARD, explanation = "L'acide urique est le produit final du métabolisme des purines. Une concentration plasmatique normale se situe entre 3 et 7 mg/100 mL, au-delà de laquelle on parle d'hyperuricémie, facteur de risque de goutte."),
        Question(8827, "Quel élément chimique est ferromagnétique?", listOf("Fer", "Cuivre", "Argent", "Or"), 0, "Science", Difficulty.HARD, explanation = "Le fer est un matériau ferromagnétique car ses atomes peuvent s'aligner sous un champ magnétique pour former un aimant permanent."),
        Question(8828, "Quel scientifique a découvert l'équation de Schrödinger?", listOf("Erwin Schrödinger", "Werner Heisenberg", "Niels Bohr", "Max Planck"), 0, "Science", Difficulty.MEDIUM, explanation = "Erwin Schrödinger a formulé cette équation fondamentale de la mécanique quantique en 1926, décrivant l'évolution dans le temps d'une particule quantique."),
        Question(8829, "Quel est le symbole chimique du naphtol?", listOf("C10H7OH", "C10H8", "C10H6OH", "C10H8O"), 0, "Science", Difficulty.HARD, explanation = "Le naphtol est un composé organique dérivé du naphtalène, dont la formule brute est C10H8, mais avec un groupe hydroxyle (OH) substituant un atome d'hydrogène, d'où la notation C10H7OH."),
        Question(8830, "Combien de cellules ganglionnaires rétiniennes a l'œil humain?", listOf("1-1.5 millions", "500000", "2-3 millions", "5 millions"), 0, "Science", Difficulty.HARD, explanation = "Les cellules ganglionnaires rétiniennes sont les neurones qui transmettent l'information visuelle de la rétine au cerveau via le nerf optique, et leur nombre est estimé entre 1 et 1,5 million par œil."),
        Question(8831, "Quel gland produit la visfatine?", listOf("Tissu adipeux", "Pancréas", "Estomac", "Foie"), 0, "Science", Difficulty.HARD, explanation = "La visfatine est une adipokine, une hormone sécrétée principalement par le tissu adipeux (graisse), et non par une glande traditionnelle comme les glandes endocrines."),
        Question(8832, "Quel est le plus grand palais connu antérieurement?", listOf("Knossos", "Persépolis", "Versailles", "Alhambra"), 0, "Science", Difficulty.HARD, explanation = "Le palais de Knossos, situé en Crète, est le plus grand palais connu de la civilisation minoenne, datant de l'âge du bronze."),
        Question(8833, "Quel scientifique a découvert les matrices?", listOf("Arthur Cayley", "Isaac Newton", "Leonhard Euler", "Augustin-Louis Cauchy"), 0, "Science", Difficulty.EXPERT, explanation = "Arthur Cayley a formalisé le concept de matrice dans les années 1850, établissant les bases de l'algèbre matricielle moderne."),
        Question(8834, "Quel est le symbole chimique du résorcinol?", listOf("C6H4(OH)2", "C6H6O2", "C6H4O2", "C6H5OH"), 0, "Science", Difficulty.HARD, explanation = "Le résorcinol est un composé organique de formule brute C6H4(OH)2, où deux groupes hydroxyle sont liés à un noyau benzénique. Ce symbole chimique représente sa structure précise."),
        Question(8835, "Quelle est la concentration de l'acide citrique dans le plasma?", listOf("4-6 mg/100 mL", "1-3 mg/100 mL", "8-10 mg/100 mL", "10-12 mg/100 mL"), 0, "Science", Difficulty.HARD, explanation = "L'acide citrique est un intermédiaire du cycle de Krebs, et sa concentration plasmatique normale se situe entre 4 et 6 mg/100 mL, reflétant un métabolisme énergétique équilibré."),
        Question(8836, "Quel élément chimique est paramagnétique?", listOf("Aluminium", "Cuivre", "Argent", "Or"), 0, "Science", Difficulty.HARD, explanation = "L'aluminium possède un électron non apparié dans sa configuration électronique, ce qui le rend sensible aux champs magnétiques et donc paramagnétique."),
        Question(8837, "Quel scientifique a découvert l'équation de Dirac?", listOf("Paul Dirac", "Werner Heisenberg", "Niels Bohr", "Max Planck"), 0, "Science", Difficulty.HARD, explanation = "Paul Dirac a formulé cette équation en 1928 pour décrire les fermions relativistes, prédisant ainsi l'existence de l'antimatière."),
        Question(8838, "Quel est le symbole chimique de la pyrogallol?", listOf("C6H3(OH)3", "C6H6O3", "C6H4O3", "C6H5OH"), 0, "Science", Difficulty.HARD, explanation = "La pyrogallol, un composé aromatique utilisé en photographie et comme antioxydant, a pour formule chimique C6H3(OH)3, indiquant un noyau benzénique avec trois groupes hydroxyle."),
        Question(8839, "Combien de neurotransmetteurs différents existent?", listOf("50-100", "10-20", "100-200", "200-300"), 0, "Science", Difficulty.HARD, explanation = "Le nombre exact de neurotransmetteurs n'est pas fixé, mais on en recense généralement entre 50 et 100 dans le système nerveux humain."),
        Question(8840, "Quel gland produit la vasopressine?", listOf("Hypophyse", "Pancréas", "Estomac", "Foie"), 1, "Science", Difficulty.HARD, explanation = "La vasopressine est une hormone produite par l'hypothalamus, pas par le pancréas, qui sécrète l'insuline et le glucagon."),
        Question(8841, "Quel est le plus grand mur défensif antique?", listOf("Grande Muraille de Chine", "Mur d'Hadrien", "Mur d'Antonin", "Murs de Jéricho"), 0, "Science", Difficulty.EASY, explanation = "La Grande Muraille de Chine, construite à partir du IIIe siècle avant J.-C., s'étend sur plus de 21 000 kilomètres, ce qui en fait la plus longue structure défensive jamais bâtie dans l'Antiquité."),
        Question(8842, "Quel scientifique a découvert le spineur?", listOf("Wolfgang Pauli", "Paul Dirac", "Werner Heisenberg", "Max Planck"), 0, "Science", Difficulty.EXPERT, explanation = "Wolfgang Pauli a introduit le concept de spineur en 1927 pour décrire le spin des particules en mécanique quantique, ce qui a permis de formuler l'équation de Pauli."),
        Question(8843, "Quel est le symbole chimique du benzisoxazole?", listOf("C7H5NO", "C7H6NO", "C7H4NO", "C7H7NO"), 0, "Science", Difficulty.HARD, explanation = "Le benzisoxazole est un composé organique hétérocyclique contenant sept atomes de carbone, cinq d'hydrogène, un d'azote et un d'oxygène, d'où sa formule brute C7H5NO."),
        Question(8844, "Quelle est la concentration de l'acide pyruvique dans le plasma?", listOf("0.5-1.5 mg/100 mL", "0.1-0.5 mg/100 mL", "2-3 mg/100 mL", "3-4 mg/100 mL"), 0, "Science", Difficulty.HARD, explanation = "L'acide pyruvique est un intermédiaire clé du métabolisme glucidique, et sa concentration plasmatique normale se situe entre 0,5 et 1,5 mg/100 mL, reflétant l'équilibre entre production et utilisation cellulaire."),
        Question(8845, "Quel élément chimique est diamagnétique?", listOf("Bismuth", "Aluminium", "Cuivre", "Fer"), 0, "Science", Difficulty.HARD, explanation = "Le bismuth est l'élément le plus diamagnétique connu, repoussant les champs magnétiques. Cette propriété vient de sa structure électronique sans électrons non appariés."),
        Question(8846, "Quel scientifique a découvert le groupe de Lorentz?", listOf("Hendrik Lorentz", "Albert Einstein", "Max Planck", "Werner Heisenberg"), 0, "Science", Difficulty.EXPERT, explanation = "Le groupe de Lorentz, nommé d'après le physicien néerlandais Hendrik Lorentz, est un groupe de transformations mathématiques qui décrit comment les mesures de l'espace et du temps changent entre deux référentiels en mouvement relatif."),
        Question(8847, "Quel est le symbole chimique du coumarine?", listOf("C9H6O2", "C9H8O2", "C9H4O2", "C9H10O2"), 0, "Science", Difficulty.HARD, explanation = "La coumarine est un composé organique de formule brute C9H6O2, présente dans certaines plantes comme la fève tonka."),
        Question(8848, "Combien d'acides aminés essentiels y a-t-il?", listOf("9", "5", "15", "20"), 0, "Science", Difficulty.HARD, explanation = "Sur les 20 acides aminés standards, 9 sont dits essentiels car le corps humain ne peut pas les synthétiser et doit les obtenir par l'alimentation."),
        Question(8849, "Quel gland produit la prolactine?", listOf("Hypophyse", "Pancréas", "Estomac", "Foie"), 0, "Science", Difficulty.EASY, explanation = "L'hypophyse, glande endocrine située à la base du cerveau, sécrète la prolactine, une hormone essentielle à la lactation."),
        Question(8850, "Quel est le plus grand pont-aqueduc romain?", listOf("Pont du Gard", "Aqueduc de Nîmes", "Pont de Alcántara", "Pont Aelianus"), 0, "Science", Difficulty.HARD, explanation = "Le Pont du Gard, situé dans le sud de la France, est le plus haut pont-aqueduc romain conservé, culminant à près de 49 mètres. Il faisait partie d'un système de 50 km acheminant l'eau vers Nîmes."),
        Question(8851, "Quel scientifique a découvert la symétrie de jauge?", listOf("Yang et Mills", "Albert Einstein", "Max Planck", "Werner Heisenberg"), 0, "Science", Difficulty.EXPERT, explanation = "Chen Ning Yang et Robert Mills ont formulé la théorie de la symétrie de jauge non abélienne en 1954, jetant les bases du modèle standard de la physique des particules."),
        Question(8852, "Quel est le symbole chimique du quinoline?", listOf("C9H7N", "C9H8N", "C9H5N", "C9H9N"), 0, "Science", Difficulty.HARD, explanation = "La quinoléine est un composé organique hétérocyclique de formule brute C9H7N, contenant un cycle benzénique fusionné à une pyridine."),
        Question(8853, "Quelle est la concentration de l'acide lactique dans le plasma?", listOf("0.5-2.0 mg/100 mL", "0.1-0.5 mg/100 mL", "3-4 mg/100 mL", "4-5 mg/100 mL"), 0, "Science", Difficulty.HARD, explanation = "L'acide lactique est un produit du métabolisme anaérobie, et sa concentration plasmatique normale à jeun se situe entre 0,5 et 2,0 mg/100 mL, reflétant l'équilibre entre production et élimination."),
        Question(8854, "Quel élément chimique est supraconducteur à basse température?", listOf("Yttrium", "Cuivre", "Argent", "Or"), 0, "Science", Difficulty.HARD, explanation = "L'yttrium, combiné avec du baryum et du cuivre, forme un oxyde céramique qui devient supraconducteur à une température relativement élevée pour ce type de matériau, soit autour de 93 K (-180 °C)."),
        Question(8855, "Quel scientifique a découvert le modèle standard?", listOf("Sheldon Glashow, Abdus Salam et Steven Weinberg", "Albert Einstein", "Max Planck", "Werner Heisenberg"), 0, "Science", Difficulty.EXPERT, explanation = "Sheldon Glashow, Abdus Salam et Steven Weinberg ont indépendamment formulé la théorie électrofaible, unifiant les forces électromagnétique et faible, ce qui leur a valu le prix Nobel de physique en 1979. Leurs travaux ont jeté les bases du modèle standard de la physique des particules."),
        Question(8856, "Quel est le symbole chimique de l'isoquinoline?", listOf("C9H7N", "C9H8N", "C9H5N", "C9H9N"), 0, "Science", Difficulty.HARD, explanation = "L'isoquinoline est un composé organique hétérocyclique de formule brute C9H7N, indiquant la présence de 9 atomes de carbone, 7 d'hydrogène et 1 d'azote."),
        Question(8857, "Combien de paires de ganglions spinaux a un humain?", listOf("31", "30", "32", "25"), 0, "Science", Difficulty.HARD, explanation = "Chaque paire de ganglions spinaux correspond à une paire de nerfs rachidiens, et l'humain en possède 31 paires."),
        Question(8858, "Quel gland produit le GnRH?", listOf("Hypothalamus", "Hypophyse", "Pancréas", "Foie"), 0, "Science", Difficulty.HARD, explanation = "L'hypothalamus produit la GnRH, une hormone qui stimule l'hypophyse pour réguler la reproduction."),
        Question(8859, "Quel est le plus grand arc de triomphe romain?", listOf("Arc de Septime Sévère", "Arc de Titus", "Arc de Trajan", "Arc de Constantin"), 0, "Science", Difficulty.HARD, explanation = "L'Arc de Septime Sévère, situé sur le Forum romain, mesure 23 mètres de haut, ce qui en fait le plus grand arc de triomphe romain conservé. Il a été érigé en 203 après J.-C. pour célébrer les victoires de l'empereur Septime Sévère et de ses fils."),
        Question(8860, "Quel scientifique a découvert la gravité quantique?", listOf("Théorique", "Albert Einstein", "Max Planck", "Werner Heisenberg"), 0, "Science", Difficulty.EXPERT, explanation = "La gravité quantique est un domaine théorique de la physique qui n'a pas encore été découvert ou confirmé expérimentalement, ce qui explique pourquoi la réponse est \"théorique\"."),
        Question(8861, "Quel est le symbole chimique de l'indole?", listOf("C8H7N", "C8H8N", "C8H5N", "C8H9N"), 0, "Science", Difficulty.HARD, explanation = "L'indole est un composé organique hétérocyclique dont la formule brute est C8H7N, ce qui signifie qu'il contient 8 atomes de carbone, 7 d'hydrogène et 1 d'azote."),
        Question(8862, "Quelle est la concentration de l'aldolase dans le plasma?", listOf("0-3 UI/L", "10-20 UI/L", "50-100 UI/L", "100-200 UI/L"), 0, "Science", Difficulty.HARD, explanation = "L'aldolase est une enzyme impliquée dans la glycolyse, principalement présente dans les muscles et le foie. Sa concentration plasmatique normale est très faible, entre 0 et 3 UI/L, car elle n'est libérée dans le sang qu'en cas de lésion tissulaire."),
        Question(8863, "Quel élément chimique est un isolant électrique?", listOf("Quartz", "Cuivre", "Argent", "Or"), 0, "Science", Difficulty.HARD, explanation = "Le quartz est un isolant électrique car il est composé de dioxyde de silicium, une structure cristalline qui ne laisse pas passer les électrons."),
        Question(8864, "Quel scientifique a découvert la SUSY?", listOf("Théorique", "Albert Einstein", "Max Planck", "Werner Heisenberg"), 0, "Science", Difficulty.EXPERT, explanation = "La supersymétrie (SUSY) est une théorie physique qui n'a pas encore été confirmée expérimentalement, donc aucun scientifique unique ne l'a découverte ; elle a été développée par plusieurs théoriciens dans les années 1970."),
        Question(8865, "Quel est le symbole chimique du carbazole?", listOf("C12H9N", "C12H8N", "C12H10N", "C12H11N"), 0, "Science", Difficulty.HARD, explanation = "Le carbazole est un composé organique hétérocyclique, sa formule brute est C12H9N, indiquant 12 atomes de carbone, 9 d'hydrogène et 1 d'azote."),
        Question(8866, "Combien de ganglions lymphatiques a le corps humain?", listOf("600-700", "300-400", "800-900", "1000-1100"), 0, "Science", Difficulty.HARD, explanation = "Le corps humain contient entre 600 et 700 ganglions lymphatiques, répartis principalement dans le cou, les aisselles et l'aine, jouant un rôle clé dans la filtration de la lymphe et la défense immunitaire."),
        Question(8867, "Quel gland produit le CRH?", listOf("Hypothalamus", "Hypophyse", "Pancréas", "Foie"), 0, "Science", Difficulty.HARD, explanation = "Le CRH (corticotropin-releasing hormone) est une hormone produite par l'hypothalamus pour réguler la réponse au stress et stimuler l'hypophyse."),
        Question(8868, "Quel est le plus grand cirque romain connu?", listOf("Circus Maximus", "Circus Flaminius", "Colosseum", "Theater Marcellus"), 0, "Science", Difficulty.EXPERT, explanation = "Le Circus Maximus, situé entre les collines du Palatin et de l'Aventin à Rome, était le plus grand cirque romain, pouvant accueillir jusqu'à 250 000 spectateurs pour des courses de chars."),
        Question(8869, "Quel scientifique a découvert les cordes de supergravité?", listOf("Théorique", "Albert Einstein", "Max Planck", "Werner Heisenberg"), 0, "Science", Difficulty.EXPERT, explanation = "Les cordes de supergravité sont un concept de la physique théorique, proposé dans les années 1970 par des chercheurs comme John Schwarz et Joël Scherk, dans le cadre de la théorie des cordes."),
        Question(8870, "Quel est le symbole chimique du dibenzothiophène?", listOf("C12H8S", "C12H10S", "C12H6S", "C12H12S"), 0, "Science", Difficulty.HARD, explanation = "Le dibenzothiophène est un composé organique soufré dont la formule chimique est C12H8S, indiquant 12 atomes de carbone, 8 d'hydrogène et 1 de soufre."),
        Question(8871, "Quelle est la concentration de l'amylase dans le plasma?", listOf("30-110 UI/L", "10-30 UI/L", "150-200 UI/L", "200-300 UI/L"), 0, "Science", Difficulty.HARD, explanation = "L'amylase est une enzyme produite principalement par le pancréas et les glandes salivaires. Sa concentration plasmatique normale se situe entre 30 et 110 UI/L, un taux élevé pouvant indiquer une pancréatite."),
        Question(8872, "Quel élément chimique a la plus grande réactivité chimique?", listOf("Fluor", "Chlore", "Brome", "Iode"), 0, "Science", Difficulty.HARD, explanation = "Le fluor est l'élément le plus électronégatif et possède la plus forte tendance à attirer des électrons, ce qui le rend extrêmement réactif, notamment avec les métaux et l'hydrogène."),
        Question(8873, "Quel scientifique a découvert les membranes D?", listOf("Théorique", "Albert Einstein", "Max Planck", "Werner Heisenberg"), 0, "Science", Difficulty.EXPERT, explanation = "Les membranes D sont un concept issu de la théorie des cordes, proposé par des physiciens théoriciens comme Joseph Polchinski, et non d'une découverte expérimentale directe."),
        Question(8874, "Quel est le symbole chimique du phénanthrène?", listOf("C14H10", "C14H8", "C14H12", "C14H6"), 0, "Science", Difficulty.HARD, explanation = "Le phénanthrène est un hydrocarbure aromatique polycyclique composé de 14 atomes de carbone et 10 d'hydrogène, d'où sa formule brute C14H10."),
        Question(8875, "Combien de vaisseaux lymphatiques a le corps humain?", listOf("~500", "~300", "~700", "~900"), 0, "Science", Difficulty.HARD, explanation = "Le corps humain compte environ 500 ganglions lymphatiques, qui sont de petits organes en forme de haricot répartis le long des vaisseaux lymphatiques, jouant un rôle clé dans la filtration de la lymphe et la défense immunitaire."),
        Question(8876, "Quel gland produit le TRH?", listOf("Hypothalamus", "Hypophyse", "Pancréas", "Foie"), 0, "Science", Difficulty.HARD, explanation = "Le TRH (thyrotropin-releasing hormone) est une hormone produite par l'hypothalamus pour stimuler la libération de TSH par l'hypophyse."),
        Question(8877, "Quel est le plus grand bâtiment public romain connu?", listOf("Panthéon", "Colosseum", "Forum de Trajan", "Theater Marcellus"), 0, "Science", Difficulty.HARD, explanation = "Le Panthéon de Rome, avec sa coupole de 43,3 mètres de diamètre, est le plus grand bâtiment public romain antique conservé intact."),
        Question(8878, "Quel scientifique a découvert les orbifolds?", listOf("Théorique", "Albert Einstein", "Max Planck", "Werner Heisenberg"), 0, "Science", Difficulty.EXPERT, explanation = "Les orbifolds sont un concept mathématique issu de la théorie des cordes, développé par des physiciens théoriciens comme Dixon, Harvey, Vafa et Witten dans les années 1980."),
        Question(8879, "Quel est le symbole chimique du benzo[b]fluorène?", listOf("C17H12", "C17H10", "C17H14", "C17H8"), 0, "Science", Difficulty.HARD, explanation = "Le benzo[b]fluorène est un hydrocarbure aromatique polycyclique composé de 17 atomes de carbone et 12 atomes d'hydrogène, d'où sa formule chimique C17H12."),
        Question(8880, "Quelle est la concentration de la lipase dans le plasma?", listOf("10-150 UI/L", "1-10 UI/L", "200-300 UI/L", "300-400 UI/L"), 0, "Science", Difficulty.HARD, explanation = "La lipase pancréatique est normalement présente à faible concentration dans le plasma, entre 10 et 150 UI/L, car elle est principalement sécrétée dans le duodénum pour digérer les graisses."),
        Question(8881, "Quel élément chimique a un nombre de masse constant?", listOf("Chaque élément", "Hydrogène", "Carbone", "Oxygène"), 0, "Science", Difficulty.HARD, explanation = "Le nombre de masse d’un élément est la somme de ses protons et neutrons, mais il peut varier selon les isotopes. Ainsi, aucun élément n’a un nombre de masse constant."),
        Question(8882, "Quel scientifique a découvert les branes?", listOf("Théorique", "Albert Einstein", "Max Planck", "Werner Heisenberg"), 0, "Science", Difficulty.EXPERT, explanation = "Le concept de branes a été développé par des physiciens théoriciens, notamment dans le cadre de la théorie des cordes, sans qu'un seul scientifique ne soit crédité de leur découverte."),
        Question(8883, "Quel est le symbole chimique du triphenylène?", listOf("C18H12", "C18H10", "C18H14", "C18H8"), 0, "Science", Difficulty.HARD, explanation = "Le triphenylène est un hydrocarbure aromatique polycyclique composé de 18 atomes de carbone et 12 atomes d'hydrogène, d'où sa formule brute C18H12."),
        Question(8884, "Combien de cellules de Leydig a un testicule?", listOf("~600 millions", "~300 millions", "~900 millions", "~1 milliard"), 0, "Science", Difficulty.HARD, explanation = "Les cellules de Leydig, situées dans les testicules, produisent la testostérone. Chaque testicule en contient environ 600 millions, un nombre nécessaire pour assurer une production hormonale suffisante."),
        Question(8885, "Quel gland produit la FSH?", listOf("Hypophyse antérieure", "Hypothalamus", "Thyroïde", "Pancréas"), 0, "Science", Difficulty.MEDIUM, explanation = "La FSH est produite par l'hypophyse antérieure, une glande endocrine située à la base du cerveau, qui régule les fonctions des gonades."),
        Question(8886, "Quel est le plus grand temple romain connu?", listOf("Temple de Jupiter Optimus Maximus", "Temple de Minerve", "Temple d'Hercule", "Temple de Vesta"), 0, "Science", Difficulty.HARD, explanation = "Le Temple de Jupiter Optimus Maximus, situé sur le Capitole à Rome, était le plus grand et le plus important temple de la Rome antique, dédié à la triade capitoline."),
        Question(8887, "Quel scientifique a découvert la dualité Seiberg-Witten?", listOf("Théorique", "Albert Einstein", "Max Planck", "Werner Heisenberg"), 0, "Science", Difficulty.EXPERT, explanation = "Nathan Seiberg et Edward Witten sont des physiciens théoriciens. Leur travail sur la dualité électromagnétique en théorie des cordes a été publié en 1994."),
        Question(8888, "Quel est le symbole chimique du benzo[a]anthracène?", listOf("C18H12", "C18H10", "C18H14", "C18H8"), 0, "Science", Difficulty.HARD, explanation = "Le benzo[a]anthracène est un hydrocarbure aromatique polycyclique composé de 18 atomes de carbone et 12 atomes d'hydrogène, d'où sa formule chimique C18H12."),
        Question(8889, "Quelle est la concentration de la glutamate déshydrogénase dans le plasma?", listOf("0-9 UI/L", "10-20 UI/L", "50-100 UI/L", "100-200 UI/L"), 0, "Science", Difficulty.HARD, explanation = "La glutamate déshydrogénase est une enzyme mitochondriale principalement présente dans le foie. Sa concentration plasmatique normale est très faible, entre 0 et 9 UI/L, et une élévation indique une atteinte hépatique sévère."),
        Question(8890, "Quel élément chimique a la plus longue demi-vie radioactive?", listOf("Uranium-238", "Thorium-232", "Samarium-147", "Potassium-40"), 0, "Science", Difficulty.HARD, explanation = "L'uranium-238 a une demi-vie d'environ 4,5 milliards d'années, ce qui le rend utile pour dater les roches anciennes et estimer l'âge de la Terre."),
        Question(8891, "Quel scientifique a découvert les modèles Calabi-Yau?", listOf("Théorique", "Albert Einstein", "Max Planck", "Werner Heisenberg"), 0, "Science", Difficulty.EXPERT, explanation = "Shing-Tung Yau a donné son nom aux variétés de Calabi-Yau, des espaces mathématiques essentiels en théorie des cordes, après avoir démontré la conjecture de Calabi en 1976."),
        Question(8892, "Quel est le symbole chimique du dibenzo[a,h]anthracène?", listOf("C26H16", "C26H14", "C26H18", "C26H12"), 0, "Science", Difficulty.HARD, explanation = "Le dibenzo[a,h]anthracène est un hydrocarbure aromatique polycyclique composé de 26 atomes de carbone et 16 atomes d'hydrogène, d'où sa formule brute C26H16."),
        Question(8893, "Combien de cellules de Sertoli a un testicule?", listOf("~300 millions", "~100 millions", "~500 millions", "~1 milliard"), 0, "Science", Difficulty.HARD, explanation = "Les cellules de Sertoli, qui soutiennent la spermatogenèse, sont environ 300 millions par testicule chez l'homme adulte."),
        Question(8894, "Quel gland produit la LH?", listOf("Hypophyse antérieure", "Hypothalamus", "Thyroïde", "Pancréas"), 0, "Science", Difficulty.MEDIUM, explanation = "La LH (hormone lutéinisante) est sécrétée par l'hypophyse antérieure, une glande endocrine située à la base du cerveau."),
        Question(8895, "Quel est le plus grand tombeau romain antique?", listOf("Mausolée d'Auguste", "Mausolée d'Hadrien", "Pyramide de Cestius", "Mausolée de Julien"), 0, "Science", Difficulty.EXPERT, explanation = "Le Mausolée d'Auguste, construit en 28 av. J.-C., est le plus grand tombeau romain antique avec un diamètre de 87 mètres. Il servait de sépulture à l'empereur Auguste et à sa famille."),
        Question(8896, "Quel scientifique a découvert la supersymétrie?", listOf("Théorique", "Albert Einstein", "Max Planck", "Werner Heisenberg"), 0, "Science", Difficulty.EXPERT, explanation = "La supersymétrie n'a pas été découverte par un scientifique unique mais est un concept théorique développé dans les années 1970 par plusieurs physiciens. Elle reste une hypothèse mathématique non confirmée expérimentalement."),
        Question(8897, "Quel est le symbole chimique du pentaphène?", listOf("C22H14", "C22H12", "C22H16", "C22H10"), 0, "Science", Difficulty.HARD, explanation = "Le pentaphène est un hydrocarbure aromatique polycyclique composé de 22 atomes de carbone et 14 atomes d'hydrogène, d'où sa formule brute C22H14."),
        Question(8898, "Quelle est la concentration de la phosphatase alcaline dans le plasma?", listOf("25-100 UI/L", "10-25 UI/L", "150-200 UI/L", "200-300 UI/L"), 0, "Science", Difficulty.HARD, explanation = "La phosphatase alcaline est une enzyme présente dans le foie, les os et les intestins. Sa concentration plasmatique normale de 25-100 UI/L reflète l'équilibre de ces tissus."),
        Question(8899, "Quel élément chimique a le nombre de masse le plus élevé?", listOf("Oganesson", "Livermorium", "Flerovium", "Copernicium"), 0, "Science", Difficulty.HARD, explanation = "L'oganesson (Og) possède le numéro atomique le plus élevé (118) et, parmi les éléments connus, le nombre de masse le plus élevé, environ 294. C'est un élément synthétique et radioactif."),
        Question(8900, "Quel scientifique a découvert la dualité AdS/CFT?", listOf("Théorique", "Albert Einstein", "Max Planck", "Werner Heisenberg"), 0, "Science", Difficulty.EXPERT, explanation = "La dualité AdS/CFT est une conjecture en théorie des cordes formulée par le physicien théoricien Juan Maldacena en 1997."),
        Question(8901, "Quel est le symbole chimique du pyrène?", listOf("C16H10", "C16H8", "C16H12", "C16H6"), 0, "Science", Difficulty.HARD, explanation = "Le pyrène est un hydrocarbure aromatique polycyclique composé de 16 atomes de carbone et 10 d'hydrogène, d'où sa formule brute C16H10."),
        Question(8902, "Combien de cellules épithéliales l'estomac produit-il par jour?", listOf("300 milliards", "100 milliards", "500 milliards", "1 trillion"), 0, "Science", Difficulty.HARD, explanation = "L'estomac renouvelle rapidement sa muqueuse pour se protéger de l'acide gastrique, produisant environ 300 milliards de cellules épithéliales par jour."),
        Question(8903, "Quel gland produit la ACTH?", listOf("Hypophyse antérieure", "Hypothalamus", "Thyroïde", "Pancréas"), 0, "Science", Difficulty.HARD, explanation = "L'ACTH est une hormone produite par l'hypophyse antérieure qui stimule les glandes surrénales à libérer du cortisol."),
        Question(8904, "Quel est le plus grand cirque antique connu?", listOf("Circus Maximus", "Circus Flaminius", "Colosseum", "Theater Marcellus"), 1, "Science", Difficulty.HARD, explanation = "Le Circus Flaminius était le plus grand cirque de la Rome antique, construit en 221 av. J.-C. pour les courses de chars, surpassant le Circus Maximus en taille."),
        Question(8905, "Quel scientifique a découvert la théorie de Twistor?", listOf("Roger Penrose", "Albert Einstein", "Max Planck", "Werner Heisenberg"), 0, "Science", Difficulty.EXPERT, explanation = "Roger Penrose a développé la théorie des twisteurs dans les années 1960 pour unifier la relativité générale et la mécanique quantique."),
        Question(8906, "Quel est le symbole chimique du coronène?", listOf("C24H12", "C24H10", "C24H14", "C24H8"), 0, "Science", Difficulty.HARD, explanation = "Le coronène est un hydrocarbure aromatique polycyclique composé de 24 atomes de carbone et 12 atomes d'hydrogène, d'où sa formule chimique C24H12."),
        Question(8907, "Quelle est la concentration de la gamma-GT dans le plasma?", listOf("8-60 UI/L", "1-8 UI/L", "100-150 UI/L", "150-200 UI/L"), 0, "Science", Difficulty.HARD, explanation = "La gamma-glutamyl transférase (gamma-GT) est une enzyme hépatique dont le taux normal dans le plasma se situe entre 8 et 60 UI/L, servant de marqueur pour détecter des lésions du foie ou des voies biliaires."),
        Question(8908, "Quel élément chimique a le plus petit diamètre atomique?", listOf("Fluor", "Hydrogène", "Hélium", "Azote"), 0, "Science", Difficulty.HARD, explanation = "Le fluor a le plus petit diamètre atomique car, dans une période du tableau périodique, le rayon atomique diminue de gauche à droite en raison de l'augmentation de la charge nucléaire."),
        Question(8909, "Quel scientifique a découvert les amplitudes d'amplification?", listOf("Théorique", "Albert Einstein", "Max Planck", "Werner Heisenberg"), 0, "Science", Difficulty.EXPERT, explanation = "L'amplitude d'amplification est un concept théorique en physique, notamment en mécanique quantique, et n'est pas attribué à un scientifique spécifique, ce qui explique la réponse \"Théorique\"."),
        Question(8910, "Quel est le symbole chimique du hexacène?", listOf("C26H16", "C26H14", "C26H18", "C26H12"), 0, "Science", Difficulty.HARD, explanation = "Le hexacène est un hydrocarbure aromatique polycyclique composé de 26 atomes de carbone et 16 atomes d'hydrogène, d'où son symbole chimique C26H16."),
        Question(8911, "Combien de cellules de Merkel a la peau?", listOf("~50 millions", "~10 millions", "~100 millions", "~200 millions"), 0, "Science", Difficulty.HARD, explanation = "Les cellules de Merkel sont des mécanorécepteurs tactiles situés dans l'épiderme, et leur densité moyenne dans la peau humaine est estimée à environ 50 millions, permettant la perception du toucher fin."),
        Question(8912, "Quel gland produit la TSH?", listOf("Hypophyse antérieure", "Hypothalamus", "Thyroïde", "Pancréas"), 0, "Science", Difficulty.MEDIUM, explanation = "La TSH, ou thyréostimuline, est sécrétée par l'hypophyse antérieure pour réguler la glande thyroïde."),
        Question(8913, "Quel est le plus grand mausolée antique?", listOf("Mausolée d'Halicarnasse", "Mausolée d'Auguste", "Mausolée d'Hadrien", "Pyramide de Khéops"), 0, "Science", Difficulty.EASY, explanation = "Le Mausolée d'Halicarnasse, construit au IVe siècle av. J.-C. pour le roi Mausole, était l'une des Sept Merveilles du monde antique, mesurant environ 45 mètres de haut."),
        Question(8914, "Quel scientifique a découvert la théorie conforme des champs?", listOf("Théorique", "Albert Einstein", "Max Planck", "Werner Heisenberg"), 0, "Science", Difficulty.EXPERT, explanation = "La théorie conforme des champs a été développée par plusieurs physiciens théoriciens, dont Alexander Polyakov, Alexander Belavin et Alexander Zamolodchikov dans les années 1970-1980."),
        Question(8915, "Quel est le symbole chimique du heptacène?", listOf("C28H18", "C28H16", "C28H20", "C28H14"), 0, "Science", Difficulty.HARD, explanation = "Le heptacène est un hydrocarbure aromatique polycyclique composé de 28 atomes de carbone et 18 atomes d'hydrogène, d'où sa formule brute C28H18."),
        Question(8916, "Quelle est la concentration de la transaminase (AST) dans le plasma?", listOf("10-40 UI/L", "1-10 UI/L", "100-150 UI/L", "150-200 UI/L"), 0, "Science", Difficulty.HARD, explanation = "L'AST est une enzyme normalement présente dans les cellules hépatiques et cardiaques. Sa concentration plasmatique de 10 à 40 UI/L correspond au taux physiologique chez un adulte sain."),
        Question(8917, "Quel élément chimique a le plus grand rayon ionique?", listOf("Iodure", "Bromure", "Chlorure", "Fluorure"), 0, "Science", Difficulty.HARD, explanation = "L'ion iodure (I⁻) possède un rayon ionique plus grand que les autres halogénures car il se situe en bas du groupe 17, avec le plus grand nombre de couches électroniques."),
        Question(8918, "Quel scientifique a découvert les anomalies quantiques?", listOf("Théorique", "Albert Einstein", "Max Planck", "Werner Heisenberg"), 0, "Science", Difficulty.EXPERT, explanation = "Le terme \"anomalies quantiques\" est un concept théorique issu de la physique quantique, et non une découverte attribuée à un scientifique particulier."),
        Question(8919, "Quel est le symbole chimique du naphthacène?", listOf("C18H12", "C18H10", "C18H14", "C18H8"), 0, "Science", Difficulty.HARD, explanation = "Le naphthacène est un hydrocarbure aromatique polycyclique composé de quatre cycles benzéniques fusionnés, d'où sa formule brute C18H12."),
        Question(8920, "Combien de corpuscules de Pacini a la peau?", listOf("~3000", "~1000", "~5000", "~10000"), 0, "Science", Difficulty.HARD, explanation = "Les corpuscules de Pacini sont des récepteurs sensoriels de la peau sensibles aux vibrations et à la pression. On en compte environ 3000 dans l'ensemble du corps humain."),
        Question(8921, "Quel gland produit la prolactine?", listOf("Hypophyse antérieure", "Hypothalamus", "Thyroïde", "Pancréas"), 1, "Science", Difficulty.EASY, explanation = "L'hypothalamus produit la prolactine via des neurones spécialisés, mais sa sécrétion est principalement régulée par l'inhibition de la dopamine."),
        Question(8922, "Quel est le plus grand arc de Noe?", listOf("Arc du Pont-Neuf", "Arc du Carousel", "Arc de l'Étoile", "Arc de la Paix"), 0, "Science", Difficulty.HARD, explanation = "L'arc du Pont-Neuf est le plus grand arc de Noé, un terme désignant les arches de ponts. Il s'agit du pont le plus ancien de Paris encore debout, dont l'arche principale mesure 20 mètres de portée."),
        Question(8923, "Quel scientifique a découvert les instantons?", listOf("Théorique", "Albert Einstein", "Max Planck", "Werner Heisenberg"), 0, "Science", Difficulty.EXPERT, explanation = "Les instantons ont été découverts par les physiciens théoriciens Alexander Polyakov, Gerard 't Hooft, et d'autres dans les années 1970, dans le cadre de la théorie quantique des champs."),
        Question(8924, "Quel est le symbole chimique du tétracène?", listOf("C18H12", "C18H10", "C18H14", "C18H8"), 1, "Science", Difficulty.HARD, explanation = "Le tétracène est un hydrocarbure aromatique polycyclique composé de quatre cycles benzéniques fusionnés, d'où sa formule brute C18H10."),
        Question(8925, "Quelle est la concentration de la transaminase (ALT) dans le plasma?", listOf("7-40 UI/L", "1-7 UI/L", "100-150 UI/L", "150-200 UI/L"), 0, "Science", Difficulty.HARD, explanation = "L'alanine aminotransférase (ALT) est une enzyme hépatique ; sa concentration plasmatique normale est de 7 à 40 UI/L, une élévation indiquant souvent une lésion du foie."),
        Question(8926, "Quel élément chimique est le plus conducteur thermique?", listOf("Argent", "Cuivre", "Or", "Aluminium"), 0, "Science", Difficulty.HARD, explanation = "L'argent possède la conductivité thermique la plus élevée de tous les éléments, devant le cuivre et l'or, grâce à sa structure cristalline et à ses électrons libres."),
        Question(8927, "Quel scientifique a découvert les monopôles magnétiques?", listOf("Théorique", "Albert Einstein", "Max Planck", "Werner Heisenberg"), 0, "Science", Difficulty.EXPERT, explanation = "Les monopôles magnétiques n'ont jamais été observés expérimentalement, mais leur existence est prédite par certaines théories physiques, notamment la mécanique quantique. Paul Dirac en a proposé l'existence théorique en 1931."),
        Question(8928, "Quel est le symbole chimique du pentacène?", listOf("C22H14", "C22H12", "C22H16", "C22H10"), 0, "Science", Difficulty.HARD, explanation = "Le pentacène est un hydrocarbure aromatique polycyclique composé de 22 atomes de carbone et 14 atomes d'hydrogène, d'où sa formule brute C22H14."),
        Question(8929, "Combien de corpuscules de Meissner a la peau?", listOf("~40000", "~10000", "~100000", "~200000"), 0, "Science", Difficulty.HARD, explanation = "Les corpuscules de Meissner sont des récepteurs tactiles situés dans la peau, principalement au niveau des zones sensibles comme les doigts, et leur nombre total est estimé à environ 40 000 chez l'adulte."),
        Question(8930, "Quel gland produit la GH?", listOf("Hypophyse antérieure", "Hypothalamus", "Thyroïde", "Pancréas"), 0, "Science", Difficulty.MEDIUM, explanation = "La GH, ou hormone de croissance, est sécrétée par l'hypophyse antérieure, une glande endocrine située à la base du cerveau."),
        Question(8931, "Quel est le plus grand phare antique?", listOf("Phare d'Alexandrie", "Phare de Colosse de Rhodes", "Phare de la Pharos", "Phare du Cap"), 0, "Science", Difficulty.HARD, explanation = "Construit au IIIe siècle av. J.-C. sur l'île de Pharos, le phare d'Alexandrie était l'une des Sept Merveilles du monde antique et culminait à environ 130 mètres."),
        Question(8932, "Quel scientifique a découvert les anomalies chirales?", listOf("Théorique", "Albert Einstein", "Max Planck", "Werner Heisenberg"), 0, "Science", Difficulty.EXPERT, explanation = "Les anomalies chirales ont été découvertes par le physicien théorique Tsung-Dao Lee et Chen Ning Yang, qui ont reçu le prix Nobel en 1957 pour leurs travaux théoriques sur la violation de la parité."),
        Question(8933, "Quel est le symbole chimique de la chrysène?", listOf("C18H12", "C18H10", "C18H14", "C18H8"), 0, "Science", Difficulty.HARD, explanation = "La chrysène est un hydrocarbure aromatique polycyclique composé de 18 atomes de carbone et 12 d'hydrogène, d'où sa formule brute C18H12."),
        Question(8934, "Quelle est la concentration de la créatinine dans le plasma?", listOf("0.6-1.2 mg/100 mL", "0.1-0.6 mg/100 mL", "2-3 mg/100 mL", "3-4 mg/100 mL"), 0, "Science", Difficulty.HARD, explanation = "La créatinine est un déchet musculaire filtré par les reins, et sa concentration plasmatique normale se situe entre 0,6 et 1,2 mg/100 mL, reflétant une fonction rénale saine."),
        Question(8935, "Quel élément chimique a le plus faible potentiel d'ionisation?", listOf("Francium", "Césium", "Rubidium", "Potassium"), 0, "Science", Difficulty.HARD, explanation = "Le francium est l'élément le plus électropositif du tableau périodique, ce qui signifie qu'il perd très facilement son électron le plus externe, d'où son potentiel d'ionisation le plus bas."),
        Question(8936, "Quel scientifique a découvert les cordes topologiques?", listOf("Théorique", "Albert Einstein", "Max Planck", "Werner Heisenberg"), 0, "Science", Difficulty.EXPERT, explanation = "Les cordes topologiques sont un concept issu de la physique théorique, et non d'une découverte expérimentale attribuée à un scientifique unique."),
        Question(8937, "Quel est le symbole chimique du tétraphène?", listOf("C22H14", "C22H12", "C22H16", "C22H10"), 0, "Science", Difficulty.HARD, explanation = "Le tétraphène est un hydrocarbure aromatique polycyclique composé de 22 atomes de carbone et 14 atomes d'hydrogène, d'où sa formule brute C22H14."),
        Question(8938, "Combien de corpuscules de Lamellar a la peau?", listOf("~100 millions", "~10 millions", "~500 millions", "~1 milliard"), 0, "Science", Difficulty.HARD, explanation = "Les corpuscules de Lamellar (ou de Pacini) sont des récepteurs sensoriels situés dans le derme. La peau humaine en contient environ 100 millions, répartis sur l'ensemble du corps."),
        Question(8939, "Quel gland produit l'TSH?", listOf("Hypophyse antérieure", "Hypothalamus", "Thyroïde", "Pancréas"), 1, "Science", Difficulty.MEDIUM, explanation = "L'hypothalamus produit la TSH (hormone thyréotrope) via la TRH, qui stimule ensuite l'hypophyse."),
        Question(8940, "Quel est le plus grand aqueduc romain?", listOf("Pont du Gard", "Aqueduc de Roquefavour", "Pont d'Alcántara", "Pont Aelianus"), 0, "Science", Difficulty.HARD, explanation = "Le Pont du Gard, dans le sud de la France, est le plus haut aqueduc romain conservé, culminant à près de 49 mètres. Il faisait partie d'un système de 50 km amenant l'eau à Nîmes."),
        Question(8941, "Quel scientifique a découvert la théorie de Toda?", listOf("Théorique", "Albert Einstein", "Max Planck", "Werner Heisenberg"), 0, "Science", Difficulty.EXPERT, explanation = "Morikazu Toda, physicien théoricien japonais, a développé cette théorie dans les années 1960 pour modéliser les interactions non linéaires dans les chaînes d'atomes."),
        Question(8942, "Quel est le symbole chimique du triphenylène?", listOf("C18H12", "C18H10", "C18H14", "C18H8"), 1, "Science", Difficulty.HARD, explanation = "Le triphenylène est un hydrocarbure aromatique polycyclique composé de 18 atomes de carbone et 10 d'hydrogène, d'où sa formule brute C18H10."),
        Question(8943, "Quelle est la concentration de l'urée dans le sang?", listOf("7-20 mg/100 mL", "1-7 mg/100 mL", "30-40 mg/100 mL", "40-50 mg/100 mL"), 0, "Science", Difficulty.HARD, explanation = "L'urée, déchet du métabolisme des protéines, est filtrée par les reins. Une concentration de 7 à 20 mg/100 mL est considérée comme normale chez l'adulte."),
        Question(8944, "Quel élément chimique a le plus haut potentiel d'ionisation?", listOf("Hélium", "Fluorine", "Azote", "Hydrogène"), 0, "Science", Difficulty.HARD, explanation = "L'hélium possède le plus haut potentiel d'ionisation car son noyau exerce une forte attraction sur ses deux électrons, très proches et formant une couche électronique complète et stable."),
        Question(8945, "Quel scientifique a découvert la théorie de Yang-Mills non-abélienne?", listOf("Yang et Mills", "Albert Einstein", "Max Planck", "Werner Heisenberg"), 0, "Science", Difficulty.EXPERT, explanation = "Chen Ning Yang et Robert Mills ont formulé cette théorie en 1954 pour généraliser l'électromagnétisme à des interactions nucléaires, jetant les bases du modèle standard de la physique des particules."),
        Question(8946, "Quel est le symbole chimique du dibenzothiophène?", listOf("C12H8S", "C12H10S", "C12H6S", "C12H12S"), 1, "Science", Difficulty.HARD, explanation = "Le dibenzothiophène est un composé organique soufré, sa formule chimique est C12H10S, indiquant 12 atomes de carbone, 10 d'hydrogène et un de soufre."),
        Question(8947, "Combien de récepteurs olfactifs a l'humain?", listOf("~400", "~100", "~800", "~1000"), 0, "Science", Difficulty.HARD, explanation = "L'humain possède environ 400 récepteurs olfactifs fonctionnels, ce qui est bien moins que chez d'autres mammifères comme les rongeurs, mais permet tout de même de distinguer des milliers d'odeurs."),
        Question(8948, "Quel gland produit la FSH?", listOf("Hypophyse antérieure", "Hypothalamus", "Thyroïde", "Pancréas"), 1, "Science", Difficulty.MEDIUM, explanation = "L'hypothalamus produit la FSH via la GnRH, qui stimule l'hypophyse. La FSH est ensuite libérée par l'hypophyse, pas directement par l'hypothalamus."),
        Question(8949, "Quel est le plus grand mur antique?", listOf("Grande Muraille de Chine", "Mur d'Hadrien", "Mur d'Antonin", "Murs de Jéricho"), 1, "Science", Difficulty.MEDIUM, explanation = "Le mur d'Hadrien, construit par l'Empire romain en Grande-Bretagne, s'étend sur 117 km, ce qui en fait le plus long mur antique."),
        Question(8950, "Quel scientifique a découvert la gravité semi-classique?", listOf("Théorique", "Albert Einstein", "Max Planck", "Werner Heisenberg"), 0, "Science", Difficulty.EXPERT, explanation = "La gravité semi-classique est un cadre théorique qui combine la relativité générale classique avec la théorie quantique des champs, sans être une théorie quantique complète de la gravité. Elle est donc principalement étudiée par des physiciens théoriciens."),
        Question(8951, "Quel est le symbole chimique du fluoranthène?", listOf("C16H10", "C16H8", "C16H12", "C16H6"), 0, "Science", Difficulty.HARD, explanation = "Le fluoranthène est un hydrocarbure aromatique polycyclique composé de 16 atomes de carbone et 10 d'hydrogène, d'où son symbole chimique C16H10."),
        Question(8952, "Quelle est la concentration du cholestérol HDL dans le plasma?", listOf("35-65 mg/100 mL", "20-35 mg/100 mL", "70-100 mg/100 mL", "100-130 mg/100 mL"), 0, "Science", Difficulty.HARD, explanation = "Le cholestérol HDL, dit \"bon cholestérol\", a une concentration plasmatique normale comprise entre 35 et 65 mg/100 mL, car il aide à éliminer l'excès de cholestérol des artères."),
        Question(8953, "Quel élément chimique a la configuration électronique la plus stable?", listOf("Gaz nobles", "Métaux alcalins", "Halogènes", "Métaux de transition"), 0, "Science", Difficulty.HARD, explanation = "Les gaz nobles possèdent une couche électronique de valence complète (8 électrons, sauf l'hélium avec 2), ce qui leur confère une stabilité chimique maximale et une très faible réactivité."),
        Question(8954, "Quel scientifique a découvert la théorie de Chern-Simons?", listOf("Théorique", "Albert Einstein", "Max Planck", "Werner Heisenberg"), 0, "Science", Difficulty.EXPERT, explanation = "Shiing-Shen Chern et James Simons ont formulé cette théorie en mathématiques et physique théorique dans les années 1970."),
        Question(8955, "Quel est le symbole chimique de l'acenaphthène?", listOf("C12H8", "C12H10", "C12H6", "C12H12"), 0, "Science", Difficulty.HARD, explanation = "L'acénaphtène est un hydrocarbure aromatique polycyclique composé de 12 atomes de carbone et 8 atomes d'hydrogène, d'où sa formule brute C12H8."),
        Question(8956, "Combien de récepteurs gustatifs a la langue?", listOf("~5000-10000", "~1000-2000", "~10000-15000", "~15000-20000"), 0, "Science", Difficulty.HARD, explanation = "La langue humaine contient entre 5 000 et 10 000 papilles gustatives, chacune abritant des cellules réceptrices capables de détecter les saveurs."),
        Question(8957, "Quel gland produit la hormone du lutéal?", listOf("Hypophyse antérieure", "Hypothalamus", "Thyroïde", "Pancréas"), 0, "Science", Difficulty.HARD, explanation = "L'hormone lutéinisante (LH) est produite par l'hypophyse antérieure, une glande endocrine située à la base du cerveau. Elle joue un rôle clé dans la régulation du cycle menstruel et de l'ovulation."),
        Question(8958, "Quel est le plus grand temple antique?", listOf("Parthénon", "Temple de Jupiter", "Temple de Diane d'Éphèse", "Temple de Hatshepsut"), 0, "Science", Difficulty.HARD, explanation = "Le Parthénon, situé sur l'Acropole d'Athènes, est souvent considéré comme le plus grand temple antique grec, dédié à la déesse Athéna."),
        Question(8959, "Quel scientifique a découvert la théorie de Toda classique?", listOf("Théorique", "Albert Einstein", "Max Planck", "Werner Heisenberg"), 0, "Science", Difficulty.EXPERT, explanation = "Morikazu Toda, un physicien théoricien japonais, a formulé cette théorie en 1967 pour modéliser les interactions non linéaires dans les chaînes de particules."),
        Question(8960, "Quel est le symbole chimique du benzo[c]phénanthrène?", listOf("C18H12", "C18H10", "C18H14", "C18H8"), 0, "Science", Difficulty.HARD, explanation = "Le benzo[c]phénanthrène est un hydrocarbure aromatique polycyclique composé de 18 atomes de carbone et 12 atomes d'hydrogène, d'où sa formule brute C18H12."),
        Question(8961, "Quelle est la concentration du cholestérol LDL dans le plasma?", listOf("130-160 mg/100 mL", "100-130 mg/100 mL", "160-190 mg/100 mL", "190-220 mg/100 mL"), 0, "Science", Difficulty.HARD, explanation = "Le cholestérol LDL, dit « mauvais cholestérol », est considéré comme normal entre 130 et 160 mg/100 mL de plasma, au-delà augmentant le risque cardiovasculaire."),
        Question(8962, "Quel élément chimique n'a pas de configuration stable?", listOf("Technétium", "Francium", "Astatine", "Plutonium"), 0, "Science", Difficulty.HARD, explanation = "Le technétium est un élément synthétique radioactif dont tous les isotopes sont instables, ce qui en fait le premier élément du tableau périodique sans isotope stable."),
        Question(8963, "Quel scientifique a découvert les théories de jauge supersymétriques?", listOf("Théorique", "Albert Einstein", "Max Planck", "Werner Heisenberg"), 0, "Science", Difficulty.EXPERT, explanation = "Les théories de jauge supersymétriques sont des concepts de physique théorique, développés par des scientifiques comme Julius Wess et Bruno Zumino, sans découverte expérimentale directe."),
        Question(8964, "Quel est le symbole chimique de l'acenaphthylène?", listOf("C12H6", "C12H8", "C12H10", "C12H12"), 0, "Science", Difficulty.HARD, explanation = "L'acenaphthylène est un hydrocarbure aromatique polycyclique de formule brute C12H6, composé de 12 atomes de carbone et 6 atomes d'hydrogène."),
        Question(8965, "Combien de glandes sébacées a la peau?", listOf("~2 millions", "~1 million", "~5 millions", "~10 millions"), 0, "Science", Difficulty.HARD, explanation = "La peau humaine contient environ 2 millions de glandes sébacées, réparties sur tout le corps sauf les paumes et les plantes, et leur fonction est de produire du sébum pour lubrifier et protéger la peau."),
        Question(8966, "Quel gland produit la hormone de relaxine?", listOf("Ovaire", "Hypophyse", "Thyroïde", "Pancréas"), 0, "Science", Difficulty.HARD, explanation = "La relaxine est une hormone principalement sécrétée par le corps jaune de l'ovaire pendant la grossesse, où elle aide à détendre les ligaments pelviens et à inhiber les contractions utérines."),
        Question(8967, "Quel est le plus grand musée antique?", listOf("Musée d'Alexandrie", "Bibliothèque d'Alexandrie", "Musée du Louvre", "Musée Britannique"), 0, "Science", Difficulty.HARD, explanation = "Le Musée d'Alexandrie, fondé au IIIe siècle av. J.-C., était un centre de recherche et d'enseignement majeur de l'Antiquité, abritant la célèbre Bibliothèque d'Alexandrie."),
        Question(8968, "Quel scientifique a découvert les théories topologiques?", listOf("Théorique", "Albert Einstein", "Max Planck", "Werner Heisenberg"), 0, "Science", Difficulty.EXPERT, explanation = "Le terme \"théorique\" ne désigne pas un scientifique spécifique, mais plutôt le domaine abstrait des mathématiques où les théories topologiques ont été développées par plusieurs chercheurs comme Henri Poincaré."),
        Question(8969, "Quel est le symbole chimique du fluorène?", listOf("C13H10", "C13H8", "C13H12", "C13H6"), 0, "Science", Difficulty.HARD, explanation = "Le fluorène est un hydrocarbure aromatique polycyclique de formule brute C13H10, composé de 13 atomes de carbone et 10 d'hydrogène."),
        Question(8970, "Quelle est la concentration du cholestérol VLDL dans le plasma?", listOf("5-30 mg/100 mL", "1-5 mg/100 mL", "50-70 mg/100 mL", "70-100 mg/100 mL"), 0, "Science", Difficulty.HARD, explanation = "Le cholestérol VLDL (lipoprotéine de très basse densité) transporte les triglycérides du foie vers les tissus, et sa concentration plasmatique normale se situe entre 5 et 30 mg/100 mL."),
        Question(8971, "Quel élément chimique a le plus grand nombre d'isotopes?", listOf("Étain", "Plomb", "Fer", "Nickel"), 0, "Science", Difficulty.HARD, explanation = "L'étain possède 10 isotopes stables, le plus grand nombre pour un élément chimique, ce qui s'explique par sa configuration nucléaire particulièrement favorable."),
        Question(8972, "Quel scientifique a découvert la dualité T?", listOf("Théorique", "Albert Einstein", "Max Planck", "Werner Heisenberg"), 0, "Science", Difficulty.EXPERT, explanation = "La dualité T est un concept de la théorie des cordes, découvert par des physiciens théoriciens dans les années 1980. Elle relie des théories de cordes apparemment différentes via des transformations mathématiques."),
        Question(8973, "Quel est le symbole chimique de la phénanthrène?", listOf("C14H10", "C14H8", "C14H12", "C14H6"), 0, "Science", Difficulty.HARD, explanation = "La phénanthrène est un hydrocarbure aromatique polycyclique composé de 14 atomes de carbone et 10 d'hydrogène, d'où son symbole C14H10."),
        Question(8974, "Combien de glandes sudoripares a la peau?", listOf("~2-3 millions", "~1 million", "~5 millions", "~10 millions"), 0, "Science", Difficulty.HARD, explanation = "La peau humaine contient entre 2 et 3 millions de glandes sudoripares, réparties sur tout le corps, avec une densité plus élevée sur la paume des mains et la plante des pieds."),
        Question(8975, "Quel gland produit la hormone inhibitrice de prolactine?", listOf("Hypothalamus", "Hypophyse", "Thyroïde", "Pancréas"), 0, "Science", Difficulty.HARD, explanation = "L'hypothalamus produit la dopamine, qui agit comme l'hormone inhibitrice de prolactine en régulant la sécrétion de prolactine par l'hypophyse."),
        Question(8976, "Quel est le plus grand grenier antique?", listOf("Grenier d'Alexandrie", "Grenier de Rome", "Grenier d'Égypte", "Grenier de Grèce"), 0, "Science", Difficulty.HARD, explanation = "Le Grenier d'Alexandrie désigne la région fertile d'Égypte qui approvisionnait l'Empire romain en blé, faisant d'Alexandrie un centre majeur de stockage et d'exportation céréalière dans l'Antiquité."),
        Question(8977, "Quel scientifique a découvert la dualité S?", listOf("Théorique", "Albert Einstein", "Max Planck", "Werner Heisenberg"), 0, "Science", Difficulty.EXPERT, explanation = "La dualité S est un concept de la théorie des cordes, développé par des physiciens théoriciens comme Edward Witten, et non par un expérimentateur."),
        Question(8978, "Quel est le symbole chimique du dibenzo[a,l]pyrène?", listOf("C26H16", "C26H14", "C26H18", "C26H12"), 0, "Science", Difficulty.HARD, explanation = "Le dibenzo[a,l]pyrène est un hydrocarbure aromatique polycyclique composé de 26 atomes de carbone et 16 atomes d'hydrogène, d'où sa formule brute C26H16."),
        Question(8979, "Quelle est la concentration des plaquettes dans le sang?", listOf("150-400 × 10³/μL", "50-150 × 10³/μL", "400-600 × 10³/μL", "600-800 × 10³/μL"), 0, "Science", Difficulty.HARD, explanation = "Les plaquettes sont des fragments cellulaires essentiels à la coagulation. Leur taux normal se situe entre 150 000 et 400 000 par microlitre de sang."),
        Question(8980, "Quel élément chimique a le plus grand nombre de valences?", listOf("Carbone", "Oxygène", "Azote", "Soufre"), 0, "Science", Difficulty.HARD, explanation = "Le carbone possède quatre électrons de valence, ce qui lui permet de former jusqu'à quatre liaisons covalentes, un nombre maximal parmi les éléments courants."),
        Question(8981, "Quel scientifique a découvert la dualité U?", listOf("Théorique", "Albert Einstein", "Max Planck", "Werner Heisenberg"), 0, "Science", Difficulty.EXPERT, explanation = "La dualité onde-particule, concept clé de la mécanique quantique, a été formalisée par Louis de Broglie, un physicien théoricien français, en 1924."),
        Question(8982, "Quel est le symbole chimique du benzo[ghi]périlène?", listOf("C22H12", "C22H10", "C22H14", "C22H8"), 0, "Science", Difficulty.HARD, explanation = "Le benzo[ghi]périlène est un hydrocarbure aromatique polycyclique composé de 22 atomes de carbone et 12 atomes d'hydrogène, d'où sa formule brute C22H12."),
        Question(8983, "Combien de fibres de collagène a la peau?", listOf("~3 kg", "~1 kg", "~5 kg", "~10 kg"), 0, "Science", Difficulty.HARD, explanation = "Le collagène est la protéine la plus abondante dans le corps humain, représentant environ 30% de ses protéines totales, et la peau en contient environ 3 kg, principalement dans le derme."),
        Question(8984, "Quel gland produit la parathormone?", listOf("Glande parathyroïde", "Hypophyse", "Thyroïde", "Pancréas"), 1, "Science", Difficulty.MEDIUM, explanation = "La parathormone est produite par les glandes parathyroïdes, situées derrière la thyroïde, et non par l'hypophyse. L'hypophyse sécrète d'autres hormones comme l'hormone de croissance."),
        Question(8985, "Quel est le plus grand tombeau antique?", listOf("Tombeau de Qin Shi Huang", "Pyramide de Khéops", "Mausolée d'Halicarnasse", "Tombeau de Darius"), 0, "Science", Difficulty.HARD, explanation = "Le tombeau de Qin Shi Huang, premier empereur de Chine, est le plus grand tombeau antique connu, abritant la célèbre armée de terre cuite. Sa construction a mobilisé des centaines de milliers d'ouvriers pendant près de 40 ans."),
        Question(8986, "Quel scientifique a découvert les conjectures en serre?", listOf("Théorique", "Albert Einstein", "Max Planck", "Werner Heisenberg"), 0, "Science", Difficulty.EXPERT, explanation = "Svante Arrhenius a formulé la première théorie quantifiant l'effet de serre en 1896, reliant le dioxyde de carbone aux températures terrestres."),
        Question(8987, "Quel est le symbole chimique de l'indène?", listOf("C9H8", "C9H6", "C9H10", "C9H4"), 0, "Science", Difficulty.HARD, explanation = "L'indène est un hydrocarbure aromatique composé de 9 atomes de carbone et 8 atomes d'hydrogène, d'où son symbole chimique C9H8."),
        Question(8988, "Quelle est la concentration de la myoglobine dans le muscle?", listOf("50-70 g/kg", "20-40 g/kg", "80-100 g/kg", "100-120 g/kg"), 0, "Science", Difficulty.HARD, explanation = "La myoglobine, protéine stockant l'oxygène, est très concentrée dans les muscles pour soutenir l'effort, atteignant 50 à 70 g/kg chez les mammifères actifs."),
        Question(8989, "Quel élément chimique est le plus densément compacté?", listOf("Osmium", "Iridium", "Platine", "Tungstène"), 1, "Science", Difficulty.HARD, explanation = "L'iridium est l'élément le plus dense, avec une densité d'environ 22,56 g/cm³, dépassant l'osmium dans des conditions standards."),
        Question(8990, "Quel scientifique a découvert la théorie des cordes hétérotiques?", listOf("Théorique", "Albert Einstein", "Max Planck", "Werner Heisenberg"), 0, "Science", Difficulty.EXPERT, explanation = "La théorie des cordes hétérotiques a été développée par David Gross, Jeffrey Harvey, Emil Martinec et Ryan Rohm en 1985, combinant des aspects des cordes bosoniques et supercordes."),
