        Question(8992, "Combien de fibres élastiques a la peau?", listOf("~10-20 g", "~1-5 g", "~30-50 g", "~50-70 g"), 0, "Science", Difficulty.HARD, explanation = "La peau contient environ 10 à 20 grammes de fibres élastiques, principalement composées d'élastine, qui lui confèrent souplesse et résilience."),
