        Question(8994, "Quel est le plus grand mausolée antique?", listOf("Mausolée d'Halicarnasse", "Pyramide de Khéops", "Tombeau de Qin Shi Huang", "Mausolée d'Auguste"), 1, "Science", Difficulty.HARD, explanation = "La pyramide de Khéops, construite vers 2560 av. J.-C., est le plus grand mausolée antique, avec une hauteur originale de 146,6 mètres. Elle servait de tombeau au pharaon Khéops de la IVe dynastie égyptienne."),
        Question(8995, "Quel scientifique a découvert la conjecture de Calabi-Yau?", listOf("Théorique", "Albert Einstein", "Max Planck", "Werner Heisenberg"), 0, "Science", Difficulty.EXPERT, explanation = "Shing-Tung Yau a démontré la conjecture de Calabi en 1976, prouvant l'existence des variétés de Calabi-Yau."),
        Question(8996, "Quel est le symbole chimique du naphtalène?", listOf("C10H8", "C10H6", "C10H10", "C10H4"), 0, "Science", Difficulty.MEDIUM, explanation = "Le naphtalène est un hydrocarbure aromatique composé de 10 atomes de carbone et 8 atomes d'hydrogène, d'où sa formule chimique C10H8."),
        Question(8997, "Quelle est la concentration de la hémoglobine fœtale dans le fœtus?", listOf("80% du total", "50% du total", "100% du total", "20% du total"), 0, "Science", Difficulty.HARD, explanation = "L'hémoglobine fœtale (HbF) représente environ 80 % de l'hémoglobine totale chez le fœtus, car elle a une affinité plus élevée pour l'oxygène que l'hémoglobine adulte, facilitant le transfert d'oxygène depuis la mère."),
